To make this discussion transparent we take a leaf out of several recent works \cite{sander2022sinkformers, vuckovic2020mathematical, geshkovski2023mathematical} 
which view Transformers as a flow maps on $\mathscr{P}(\mathbb{S}^{d-1})$---the space of probability measures over the unit sphere $\mathbb{S}^{d-1}$---realized by an interacting particle system: viewing each token as a particle, given an initial sequence of particles $(x_1(0),\ldots,x_n(0))\in(\mathbb{S}^{d-1})^n$, one considers 
\begin{equation} \label{eq: ips}
    \dot{x}_i(t) = v[\mu(t)](t,x_i(t)) \hspace{1cm} \text{ for } t\in[0,T],
\end{equation}
for all $i\in[n]$; here $\mu(t)=\frac{1}{n}\sum_{j=1}^n \updelta_{x_j(t)}$ denotes the empirical measure.

\label{thm: targets.atoms}
   Suppose $d\geqslant3$.
   Consider data 
   \eqref{eq: data} such that 
   \begin{enumerate}
   \item There exists $w_0\in\mathbb{S}^{d-1}$ such that
   \begin{equation} \label{eq: first.assp}
       w_0\notin\bigcup_{i\in[N]} \mathrm{supp}(\mu_0^i). 
   \end{equation} 
   \item For any $i\in[N]$, we have $\mu^i_1=\updelta_{x^i}$.
   \end{enumerate}
   Then for any $T>0$ and $\varepsilon>0$, there exists $\theta\in L^\infty((0,T);\Uptheta)$ such that for any $i\in[N]$, the unique solution $\mu^i\in\mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to \eqref{eq: cauchy.pb} with data $\mu_0^i$ and parameters $\theta$ satisfies
   \begin{equation*}
       \mathsf{W}_2\left(\mu^i(T),\mu_1^i\right)\leqslant\varepsilon.
   \end{equation*}
   Moreover, $\theta$ can be chosen piecewise constant, with  $O(d\cdot N)$ switches, and $$\|\theta\|_{L^\infty((0,T);\Uptheta)}=O\left(\frac{d\cdot N}{T}+\log\frac{1}{\varepsilon}\right).$$

 \label{thm: main.result}
Suppose $d\geqslant3$. Consider data \eqref{eq: data} such that
\begin{enumerate}
    \item There exist $w_0,w_1\in\mathbb{S}^{d-1}$ such that 
    \begin{equation} \label{eq: assumption.hole}
        w_0\notin\bigcup_{i\in[N]} \mathrm{supp}(\mu_0^i) \quad \text{ and } \quad w_1\notin\bigcup_{i\in[N]}\mathrm{supp}(\mu_1^i). 
    \end{equation}  
    \item For any $i\in[N]$, there exists $\mathsf{T}^i\in L^2(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$ such that $\mathsf{T}^i_{\#}\mu_0^i=\mu_1^i$.
\end{enumerate}
Then for any $T>0$ and $\varepsilon>0$, there exists $\theta\in L^\infty((0,T);\Uptheta)$ such that for any $i\in[N]$, the unique solution $\mu^i\in\mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to \eqref{eq: cauchy.pb} with data $\mu_0^i$ and parameters $\theta$ satisfies
    \begin{equation*}
        \mathsf{W}_2\left(\mu^i(T),\mu_1^i\right)\leqslant\varepsilon.
    \end{equation*}
    Moreover, $\theta$ can be chosen piecewise constant.

Recall the Wasserstein-$p$ distance for $p\geqslant 1$:
\begin{equation} \label{eq: wass.dist}
    \mathsf{W}_p^p(\mu,\nu):=\inf_{\pi\in \mathcal{C}(\mu,\nu)}\int d_g(x,y)^p\pi(\, \mathrm{d} x,\, \mathrm{d} y),
\end{equation}
where $\mathcal{C}(\mu,\nu)$ denotes all couplings between $\mu$ and $\nu$ (see \cite{villani2009optimal} for details).

 \label{prop: targets.atoms}
Suppose $\mu_0^i\in \mathscr{P}(\mathbb{S}^{d-1})$ for $i\in[N]$, are such that 
\begin{equation*}
\mathrm{supp}(\mu_0^i)\text{ is contained in an open hemisphere.}
\end{equation*} 
Fix $\bm{\mathit{B}}\in \mathscr{M}_{d\times d}(\mathbb{R})$. Then, for any $i\in[N]$, there exists $z^i\in \mathrm{conv}_g\,\mathrm{supp}(\mu_0^i)$ such that the following holds. For any $\varepsilon>0$, there exists $T>0$ such that, the unique solution $\mu^i$ to
\begin{equation} \label{eq: cauchy.pb.W=0}
\begin{cases}
\partial_t \mu^i(t)+\mathrm{div}\left(\bm{\mathsf{P}}^\perp_x\mathscr{A}_{\bm{\mathit{B}}}[\mu^i(t)]\mu^i(t)\right)=0 &\text{ on } [0,T]\times\mathbb{S}^{d-1}\\
\mu^i(0)=\mu_0^i &\text{ on } \mathbb{S}^{d-1}   
\end{cases}
\end{equation}
satisfies
\begin{equation*}
\mathsf{W}_{\infty}\left(\mu^i(T),\updelta_{z^i}\right)\leqslant \varepsilon.
\end{equation*}

Moreover if
\begin{equation*}
\mathrm{supp}(\mu_0^i)\cap \mathrm{supp}(\mu_0^j)=\varnothing
\end{equation*}
for all $i\neq j\in[N]$ then $z^i\neq z^j$ for all $i\neq j\in[N]$.

\begin{equation*}
\mathrm{supp}(\mu_0^i)\text{ is contained in an open hemisphere.}
\end{equation*}


It suffices to show the result for a single measure. We therefore drop indices to lighten the notation.
Suppose\footnote{$\upsigma_d$ henceforth denotes the normalized spherical Lebesgue measure, i.e. the uniform measure.}
\begin{equation*}
    \upsigma_d(\mathrm{conv}_g\,\mathrm{supp}(\mu_0))>0.
\end{equation*}
Since $\bm{\mathit{V}}=I_d$, and $\mathrm{supp}(\mu_0)$ being contained in a half-sphere, for all 
$x\in \mathrm{supp}(\mu_0)$ we have
\begin{equation}\label{eq: attention.b.1}
    \|\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x)\|>0,
\end{equation}
and
\begin{equation}\label{eq: attention.b.2}
    \gamma(x):=\frac{\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x)}{\|\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x)\|}\in \mathrm{int}\left(\mathrm{conv}_g\,\mathrm{supp}(\mu_0)\right).
\end{equation}
Now fix $\tau>0$ and $x_0\in\partial \mathrm{conv}_g\,\mathrm{supp}(\mu_0)$, and consider $x$ solving
\begin{equation}\label{eq: char.flow}
    \begin{cases}
        \dot{x}(t)=\bm{\mathsf{P}}^\perp_{x(t)}\left(\mathscr{A}_{\bm{\mathit{B}}}[\mu(t)](x(t))\right)\quad t\in [0,\tau]\\
        x(0)=x_0.
    \end{cases}
\end{equation}
We Taylor expand: 
\begin{align*}
    \left\langle x(\tau), \gamma(x_0) \right\rangle = \left\langle x_0, \gamma(x_0) \right\rangle+ \tau\left\langle \bm{\mathsf{P}}^\perp_{x_0}(\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0)), \gamma(x_0) \right\rangle+O(\tau^2).
\end{align*}
Using $\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0)=\bm{\mathsf{P}}^\perp_{x_0}(\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0))+ \left\langle \mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0),x_0 \right\rangle x_0 $ as well as \eqref{eq: attention.b.1}, we deduce
\begin{equation*}
   \tau\left\langle \bm{\mathsf{P}}^\perp_{x_0}(\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0)), \gamma(x_0)\right\rangle=\tau  \frac{\|\bm{\mathsf{P}}^\perp_{x_0}(\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0))\|}{\|\mathscr{A}_{\bm{\mathit{B}}}[\mu_0](x_0)\|} >0.
\end{equation*}
Therefore $\left\langle x(\tau), \gamma(x_0) \right\rangle> \left\langle x_0, \gamma(x_0) \right\rangle$ for $\tau$ small enough. In view of \eqref{eq: attention.b.2}, we deduce
\begin{equation*}
    x(\tau)\in \mathrm{int}(\mathrm{conv}_g\,\mathrm{supp}(\mu_0)).
\end{equation*}
This entails that $t\mapsto \mathrm{conv}_g\,\mathrm{supp}(\mu(t))$ is strictly non-increasing (in the sense of set inclusion) for short times, i.e.
\begin{equation}\label{eq: set.inclusion}
        \mathrm{conv}_g\,\mathrm{supp}(\mu(\tau))\subset \mathrm{conv}_g\,\mathrm{supp}(\mu_0)
\end{equation}
for $\tau$ small enough. By the Lipschitz character of \eqref{eq: char.flow}, we also gather that 
$$\upsigma_d(\mathrm{conv}_g\,\mathrm{supp}(\mu(t)))>0$$
for all finite $t\geqslant 0$.
Therefore we can bootstrap the argument for obtaining \eqref{eq: set.inclusion} to deduce that $t\mapsto \mathrm{conv}_g\,\mathrm{supp}(\mu(t))$ is strictly non-increasing over $\mathbb{R}_{\geqslant 0}$, and we also see that 
\begin{equation}\label{eq: lebesgue.going.zero}
\lim_{t\to+\infty}\upsigma_d(\mathrm{conv}_g\,\mathrm{supp}(\mu(t)))=0. 
\end{equation}
We use \eqref{eq: lebesgue.going.zero} and induction over the dimension $d$ to conclude. Indeed note that in $d=2$, \eqref{eq: lebesgue.going.zero} and the Portmanteau theorem yield
\begin{equation} \label{eq: d=1.case}
    \lim_{t\to +\infty}\mathsf{W}_\infty(\mu(t),\delta_{x^*})=0
\end{equation}
for some $x^*\in \mathbb{S}^1$ depending only on $\mu_0$. 
Now suppose $d=3$. By \eqref{eq: lebesgue.going.zero} and the Portmanteau theorem, for every $\varepsilon_1>0$ there exist $T_{\varepsilon_1}>0$ and $\mu_{\varepsilon_1}^0\in \mathscr{P}(\mathbb{S}^{d-1})$ such that $   \mathrm{supp}(\mu_{\varepsilon_1}^0)\subset \mathbb{S}^1\cap \{x\colon x_2>0\}$ and
\begin{equation} \label{eq: first.winfty}
\mathsf{W}_{\infty}\left(\mu(T_{\varepsilon_1}),\mu_{\varepsilon_1}^0\right)\leqslant \varepsilon_1.
\end{equation}
By virtue of \eqref{eq: d=1.case}, for every $\varepsilon_2>0$ there exist $T_{\varepsilon_2}>0$ and $x^*_{\varepsilon_1}$ (depending on $\varepsilon_1$ through the initial measure $\mu_{\varepsilon_1}$) such that the solution $\mu_{\varepsilon_1}$ to
\begin{equation*}
\begin{cases}
\partial_t\mu_{\varepsilon_1}+\mathrm{div}\left(\bm{\mathsf{P}}^\perp_x\mathscr{A}_{\bm{\mathit{B}}}[\mu_{\varepsilon_1}(t)]\mu_{\varepsilon_1}\right)=0 &\text{ on } [T_{\varepsilon_1},T_{\varepsilon_1}+T_{\varepsilon_2}]\times \mathbb{S}^{d-1}\\
    \mu_{\varepsilon_1}(T_{\varepsilon_1})=\mu_{\varepsilon_1}^0 &\text{ on } \mathbb{S}^{d-1}
\end{cases}
\end{equation*}
satisfies
\begin{equation} \label{eq: second.winfty}
\mathsf{W}_{\infty}\left(\mu_{\varepsilon_1}(T_{\varepsilon_2}+T_{\varepsilon_1}),\delta_{x^*_{\varepsilon_1}}\right)\leqslant \varepsilon_2.
\end{equation}
Combining \eqref{eq: first.winfty}, \eqref{eq: second.winfty} with the triangle inequality and \Cref{lem: gronwall.transfer.plan}, we have
\begin{align*}
\mathsf{W}_\infty\left(\mu(T_{\varepsilon_2}+T_{\varepsilon_1}),\delta_{x^*_{\varepsilon_1}}\right)
&\leqslant \mathsf{W}_\infty\left(\mu(T_{\varepsilon_2}+T_{\varepsilon_1}),\mu_{\varepsilon_1}(T_{\varepsilon_2}+T_{\varepsilon_1})\right)\\
&\hspace{1cm}+\mathsf{W}_\infty\left(\mu_{\varepsilon_1}(T_{\varepsilon_2}+T_{\varepsilon_1}),\delta_{x^*_{\varepsilon_1}}\right)\\
&\leqslant O\left(e^{e^{T_{\varepsilon_2}}}\right)\mathsf{W}_\infty\left(\mu(T_{\varepsilon_1}),\mu_{\varepsilon_1}\right)+\varepsilon_2\\
    &\leqslant O\left(e^{e^{T_{\varepsilon_2}}}\right)\varepsilon_1+\varepsilon_2,
\end{align*}
where the implicit constants are independent of $\varepsilon_1,\varepsilon_2$.
By compactness, there exists $x^*\in\mathbb{S}^1$ such that for any sequence $\varepsilon_{1,n}\to 0$ as $n\to +\infty$, there is a subsequence $\{\varepsilon_{1,n_k}\}_{k\in \mathbb{N}}$ such that $x_{\varepsilon_{1,n_k}}\to x^*$ as $k\to+\infty$. 
We relabel this subsequence as $\varepsilon_{1,n}$ and the associated sequence of times by $\{T_{\varepsilon_{1,n}}\}_{n\in\mathbb{N}}$. 
Now note that
\begin{align}
    \mathsf{W}_{\infty}\left(\mu(T_{\varepsilon_{2}}+T_{\varepsilon_{1,n}}),\delta_{x^*}\right)&\leqslant O\left(e^{e^{T_{\varepsilon_2}}}\right)\varepsilon_{1,n}+\varepsilon_2+d_g\left(x_{\varepsilon_{1,n}}^*,x^*\right). \label{eq: triangle}
\end{align}
Moreover, there exists some $n(\varepsilon)\geqslant 1$ such that 
\begin{equation*}
    d_g\left(x_{\varepsilon_{1,n}}^*,x^*\right)\leqslant \frac{\varepsilon}{3}
\end{equation*}
for all $n\geqslant n(\varepsilon)$.
We set $\varepsilon_2=\frac{\varepsilon}{3}$ and we choose $n\geqslant n(\varepsilon)$ large enough so that
\begin{equation*}
    O\left(e^{e^{T_{\varepsilon_2}}}\right)\varepsilon_{1,n}\leqslant \frac{\varepsilon}{3}.
\end{equation*}
Coming back to \eqref{eq: triangle}, we find 
\begin{equation*}
    \mathsf{W}_{\infty}\left(\mu\left(T_{\varepsilon_{1,n}}+T_{\frac{\varepsilon}{3}}\right),\delta_{x^*}\right)\leqslant \varepsilon
\end{equation*}

for $n\geqslant n(\varepsilon)$. Therefore, we found a sequence of positive times $\{T_n\}_{n\in \mathbb{N}}$ with $T_n=T_{\varepsilon_{1,n}}+T_{\frac{\varepsilon}{3}}$ for which $\mu_n=\mu(T_n)$ converges to $\delta_{x^*}$ in $\mathsf{W}_\infty$. Thanks to  \eqref{eq: set.inclusion}, the convergence does not depend on the sequence of times. Indeed, for every $t\geqslant T_n$, we have
\begin{align*}
    \mathsf{W}_\infty(\mu(t),\delta_{x^*})\leqslant\max_{y\in \mathrm{conv}_g\mathrm{supp}(\mu(t))}d_g(y,x^*)&\leqslant \max_{y\in \mathrm{conv}_g\mathrm{supp}(\mu_n)}d_g(y,x^*)\\
    &\leqslant\max_{y\in B(x^*,\mathsf{W}_\infty(\mu_n,\delta_{x^*}))}d_g(y,x^*)\\
    &=2\mathsf{W}_\infty(\mu_n,\delta_{x^*})\\
    &\leqslant 2\varepsilon
\end{align*}
where $B_n\coloneqq B(x^*,\mathsf{W}_\infty(\mu_n,\delta_{x^*}))$ is the ball on $\mathbb{S}^{d-1}$ centered at $x^*$ with radius $\mathsf{W}_\infty(\mu_n,\delta_{x^*})$. As $B_n$ is geodesically convex, and since $\mathrm{supp}(\mu_n)\subset B_n$, one has  $\mathrm{conv}_g\mathrm{supp}(\mu_n)\subset B_n$.

The cases $d>3$ follow by repeating the above argument.

 \label{cl: cluster.rate}
Consider the setting of \Cref{prop: targets.atoms}, for a fixed index $i$ (which we remove), and $\bm{\mathit{B}}\equiv0$. Let $x_0\in\mathrm{conv}_g\,\mathrm{supp}(\mu_0)$ be the limit of $\mu(t)$.
Let $\varepsilon>0$ and set 
\begin{equation*}
T_\varepsilon:=
\inf \left\{t\geqslant 0\colon \mathsf{W}_2(\mu(t),\updelta_{x_0})\leqslant \varepsilon\right\}.
\end{equation*}
Then 
\begin{equation*} 
T_\varepsilon=O\left(\log\frac{1}{\varepsilon}\right).
\end{equation*}

 \label{prop: compression}
Suppose $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$, $i\in[N]$, have no atoms, and satisfy
\begin{equation*}
\mathrm{conv}_g\,\mathrm{supp}(\mu^i_0)\cap\mathrm{conv}_g\,\mathrm{supp}(\mu_0^j)=\varnothing
\end{equation*}
for $i\neq j$. Fix $M\geqslant1$, and for any $i\in[N]$ consider
\begin{equation*}
    \mu^i_1:=\sum_{k=1}^M \alpha_k^i \updelta_{x_{k}^i}
\end{equation*}
where $x_k^i\in\mathrm{conv}_g\,\mathrm{supp}(\mu_0^i)$, with $x_k^i = x_{k'}^j$ if and only if $(k, i) = (k', j)$, and where $\alpha_k^i\geqslant 0$ with $\sum_{k=1}^M\alpha_k^i=1$. Then for any $T>0$ and $\varepsilon>0$ there exist piecewise constant $(\bm{\mathit{W}},\bm{\mathit{V}},b):[0,T]\to\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d)$ such that for $i\in[N]$, the corresponding unique solution $\mu^i\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to \eqref{eq: neural.pde.sphere} with data $\mu_0^i$ and these parameters satisfies
\begin{equation*}
\mathrm{conv}_g\,\mathrm{supp}\left(\mu^i(T)\right)\cap\mathrm{conv}_g\,\mathrm{supp}\left(\mu^j(T)\right)=\varnothing
\end{equation*}
for $i\neq j$, and 
\begin{equation*}
\mathsf{W}_2\left(\mu^i(T),\mu_1^{i}\right)\leqslant\varepsilon.
\end{equation*}

  We split
\begin{equation*}
    [0,T]=\bigcup_{i\in[N]} [T_{i-1},T_{i}],
\end{equation*}
where $0=T_0<T_1<\ldots<T_N=T$ are to be determined later on. 
We look to apply \Cref{lem: tubular.mass.movement} separately within each interval, thus, dealing with one measure at a time. Namely, the parameters take the form
\begin{equation*}
    (\bm{\mathit{W}},\bm{\mathit{U}},b)(t)=\sum_{i=1}^N (\bm{\mathit{W}}_i,\bm{\mathit{U}}_i,b_i)(t)1_{[T_{i-1},T_i)}(t),
\end{equation*}
where $(\bm{\mathit{W}}_i,\bm{\mathit{U}}_i,b_i)$ are, roughly speaking, piecewise constant parameters stemming from a repeated application of \Cref{lem: tubular.mass.movement}. We critically use \eqref{eq: eq.tubular.mass.movement} to ensure that when we act on the $i$-th measure in $[T_{i-1}, T_i]$, all the other measures remain invariant, so 
\begin{equation} \label{eq: init.invariant}
 \mu^i(T_{i-1}) = \mu_0^i.   
\end{equation}
Therefore, we take $i\in[N]$ to be arbitrary. We proceed in three steps.

\subsubsection*{Step 1. Partitioning each support into $M$ pieces}

Let $\mathscr{C}^i:=\mathrm{supp}(\mu^i_0)$, and consider a partition $\{\mathscr{C}^i_k\}_{k\in[M]}$ of $\mathscr{C}^i$ consisting of pairwise disjoint sets with connected interiors and satisfying
\begin{equation*}
    \mu_0^i(\mathscr{C}_k^i):=\alpha_k^i.
\end{equation*}
Namely
\begin{equation*}
\mathscr{C}^i=\bigcup_{k\in[M]} \mathscr{C}^i_k
\end{equation*}
with $\mathscr{C}_k^i\cap \mathscr{C}_{k'}^i=\varnothing$ if $k\neq k'$ (see \Cref{fig: shattering}).

\begin{figure}[!ht]
    \centering
    \includegraphics[scale=0.6]{figures/figure-2.pdf}
    \caption{Partitioning $\mathscr{C}^i:=\mathrm{supp}(\mu^i_0)$ into $M$ pieces with connected interiors.}
    \label{fig: shattering}
\end{figure}

\subsubsection*{Step 2. Packing each part $\mathscr{C}_k^i$ with balls}

We henceforth fix an arbitrary $i\in[N]$ and $k\in[M]$.
Let $\delta>0$ to be fixed and determined later on. Consider a packing of $\mathscr{C}_k^i$ consisting of $\mathsf{N}_{k}^i(\delta)\geqslant1$ disjoint open balls\footnote{Recall that all balls are considered as subsets of the sphere, so taken with respect to the geodesic distance, as in \eqref{eq: geodesic.ball.def}.} 
\begin{equation*}
B(z_{n,i,k},R_{n,i,k})\subset\mathscr{C}_k^i\hspace{1cm}\text{ for } n\in[\mathsf{N}_{k}^i(\delta)],
\end{equation*}
with $z_{n,i,k}\in \mathbb{S}^{d-1}$ and $R_{n,i,k}>0$, such that
\begin{equation}\label{eq: reminder.packing}
    \mu_0^i\left(\bigcup_{n\in[\mathsf{N}_{k}^i(\delta)]} B(z_{n,i,k},R_{n,i,k})\right)=\alpha_k^i-\delta.
\end{equation}

We now define a target ball contained in $\mathscr{C}_k^i$ to which we aim to send the mass contained in the packing \eqref{eq: reminder.packing}.
Fix the anchor point $x_{k}^i\in \mathrm{int}\left(\mathscr{C}^i_k\right)$, and let $\eta>0$ be arbitrary and to be determined later on (the same for all indices $(i, k)\in[N]\times[M]$), but also small enough so that
\begin{equation*}
\mathscr{B}_k^i:=B(x_{k}^i,\eta)\subset\mathrm{int}\left(\mathscr{C}^i_k\right).
\end{equation*}
We also choose the target ball $\mathscr{B}_k^i$ to satisfy $\mathscr{B}_k^i\subset B(z_{n,i,k},R_{n,i,k})$ for some $n\in[\mathsf{N}_k^i(\delta)]$ (see \Cref{fig: packing}).


\subsubsection*{Step 3. Sending most of the mass to $\mathscr{B}_k^i$}

\begin{figure}[!ht]
    \centering
    \includegraphics[scale=0.55]{figures/figure-3.pdf}
    \caption{ Step 2: packing the piece $\mathscr{C}_k^i$ of the partition of $\mathscr{C}^i=\mathrm{supp}(\mu_0^i)$ with balls whose union has mass $\mu_0^i(\mathscr{C}_k^i)-\delta$. A single anchor
    point $x_k^i$ lies in this piece. The goal of Step 3 is to repeatedly use \Cref{lem: tubular.mass.movement} to transfer the mass of each ball to the one highlighted in blue. }
    \label{fig: packing}
\end{figure}


As $\mathrm{int}\left(\mathscr{C}^i_k\right)$ is connected and thus path-connected (both are equivalent for open sets in our setup), for every $n\in[\mathsf{N}_{k}^i(\delta)]$ we can find a sequence of open balls $\{\mathscr{B}_{\ell,n}\}_{0\leqslant\ell\leqslant L_{k, n}^i}\subset \mathscr{C}_k^i$ satisfying
\begin{equation}\label{eq: homotopy}
    \begin{aligned}
        &\mathscr{B}_{0,n}=B(z_{n,i,k},R_{n,i,k}),\\ 
        &\mathscr{B}_{\ell,n}\cap \mathscr{B}_{\ell+1,n}\neq \varnothing,\\
        &\mathscr{B}_{L_{n},n}=\mathscr{B}_k^i,\\
        &\mathscr{B}_{\ell,n}\cap\mathscr{B}_{\ell',n}=\varnothing\hspace{0.5cm}\text{ if }|\ell'-\ell|\geqslant 2.
    \end{aligned}
\end{equation}
Set $L_k^i:=\max_{n\in[\mathsf{N}_{k}^i(\delta)]} L_{n}$ and  fix an arbitrary $\overline{\varepsilon}>0$ to be determined later on. 
We apply \Cref{lem: tubular.mass.movement} for each piece $k\in[M]$ and $n\in[\mathsf{N}_k^i(\delta)]$---recalling \eqref{eq: init.invariant}---to find piecewise constant $(\bm{\mathit{W}}_i, \bm{\mathit{U}}_i, b_i):[T_{i-1}, T_i]\to\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d$ with at most
\begin{equation*}
    K\cdot \max_{k\in[M]} \mathsf{N}_k^i(\delta)\cdot L_k^i
\end{equation*}
switches, such that
\begin{align}\label{eq: mass.lower.bound}
    \mu^i(T_i,\mathscr{B}_k^i)&\geqslant (1-\overline{\varepsilon})^{L_k^i} \mu_0^i\left(\bigcup_{n\in[\mathsf{N}_{k}^i(\delta)]}\bigcup_{\ell=0}^{L_{n}} \mathscr{B}_{\ell, n} \right)\nonumber\\
    &\geqslant (1-\overline{\varepsilon})^{L_k^i} \mu_0^i\left(\bigcup_{n\in[\mathsf{N}_{k}^i(\delta)]} B(z_{n,i,k},R_{n,i,k})\right)\nonumber\\
    &\overset{\eqref{eq: reminder.packing}}{=}(1-\overline{\varepsilon})^{L_k^i} \left(\alpha_k^i-\delta \right).
\end{align}
Moreover, $\mu^i(T_i)=\Phi^{T_i}_\#\mu^i_0$, and $\Phi^{T_i}(x)=x$ for all $x\notin \mathrm{supp}(\mu_0^i)$ because of \eqref{eq: eq.tubular.mass.movement}. 
Using Kantorovich-Rubinstein duality,
\begin{align*}
&\hspace{0.1cm}\mathsf{W}_1(\mu^i(T_i),\mu^i_1) = \sup_{\mathrm{Lip}(\phi)\leqslant 1}\left|\int\phi(\mu^i(T_i)-\mu_1^i)\right|\\
    &\hspace{0.2cm}= \sup_{\mathrm{Lip}(\phi)\leqslant 1}\left|\sum_{k=1}^M\int_{\mathscr{B}_k^i}\phi(\mu^i(T_i)- \mu_1^i)+\int_{\mathbb{S}^{d-1}\setminus(\bigcup_{k\in[M]}\mathscr{B}_k^i)}\phi(\mu^i(T_i)-\mu_1^i)\right|.
\end{align*}
Note that without loss of generality we can maximize over all $\phi\in W^{1,\infty}(\mathbb{S}^{d-1})$ with $\mathrm{Lip}(\phi)\leqslant1$ and of average $0$. Such functions have an $L^\infty(\mathbb{S}^{d-1})$--norm bounded by the length of any geodesic, namely $2\pi$.\footnote{We can write $\phi=\psi+\int\phi$ (vertical shift), and clearly $\|\psi\|_{\mathrm{Lip}(\mathbb{S}^{d-1})}\leqslant1$. Since $\psi$ has average $0$ and is continuous, $\psi(x)=0$ for some $x\in\mathbb{S}^{d-1}$. Whence $|\psi(x)|\leqslant d_g(x,0)$ for $x\in\mathbb{S}^{d-1}$.} 
Going term by term in the identity above, using \eqref{eq: mass.lower.bound} and the definition of $\mathscr{B}_k^i$ we find
\begin{align*}
\int_{\mathscr{B}_k^i} \phi(\mu^i(T_i) -\mu_1^i)&=
    \int_{\mathscr{B}_k^i} \phi\mu^i(T_i) -\alpha_k^i\phi(x_k^i)\\
    &=\int_{\mathscr{B}_k^i} \phi\mu^i(T_i) -(\alpha_k^i-\overline{\delta})\phi(x_k^i)-\overline{\delta}\phi(x_k^i)\\
    &=\int_{\mathscr{B}_k^i} (\phi(x)-\phi(x_k^i))\mu^i(T_i) -\overline{\delta}\phi(x_k^i),
\end{align*}
where $\overline{\delta}:=\alpha_k^i-\mu^i(T_i,\mathscr{B}_k^i)>0$. 
By virtue of \eqref{eq: homotopy} and \eqref{eq: eq.tubular.mass.movement} we also gather that $\mu(T_i,\mathscr{C}_k^i)=\mu_0(\mathscr{C}_k^i)=\alpha_k^i$, and therefore 
$$\alpha_k^i=\mu^i(T_i,\mathscr{C}_k^i)\geqslant \mu^i(T_i,\mathscr{B}_k^i).$$
Owing to \eqref{eq: mass.lower.bound}, we find
\begin{equation*}
    \overline{\delta}\leqslant \alpha_k^i-(1-\overline{\varepsilon})^{L_k^i}(\alpha_k-\delta),
\end{equation*}
which clearly goes to $0$ as $\overline{\varepsilon}$ and $\delta$ go to $0$. Therefore
\begin{equation*}
    \left|\int_{\mathscr{B}_k^i} \phi(\mu^i(T_i) -\mu_1^i)\right|\leqslant \eta \mu^i(T_i,\mathscr{B}_k^i)+\overline{\delta}\|\phi\|_{L^\infty(\mathbb{S}^{d-1})},
\end{equation*}
which tends to $0$ as $\delta$, $\overline{\varepsilon}$ and $\eta$ tend to zero. On the other hand, thanks to \eqref{eq: mass.lower.bound},
\begin{align*}
\left|\int_{\mathbb{S}^{d-1}\setminus(\bigcup_{k\in[M]}\mathscr{B}_k^i)}\phi(\mu^i(T_i)-\mu_1^i)\right|&\leqslant 2\pi \mu^i\left(T_i,\mathbb{S}^{d-1}\setminus\bigcup_{k\in[M]} \mathscr{B}_k^i\right)\\
    &\leqslant 2\pi \left|1-(1-\overline{\varepsilon})^{\max_{k\in[M]} L_k^i}\sum_{k=1}^M(\alpha_k^i-\delta)\right|\\
    &\leqslant 2\pi \left|1-(1-\overline{\varepsilon})^{\max_{k\in[M]} L_k^i}(1-M\delta)\right|,
\end{align*}
which also tends to 0 as $\overline{\varepsilon}$ and $\delta$ tend to $0$.
Therefore, we can choose $\overline{\varepsilon},\delta$ and $\eta$ small enough so that
\begin{equation*}
    \mathsf{W}_1\left(\mu^i(T_i),\mu_1^i\right)\leqslant \varepsilon.
\end{equation*}
We can conclude since all Wasserstein distances are equivalent on $\mathbb{S}^{d-1}$.

\label{rem: nb.disc.clustering}
   Looking at the proof, we deduce that $(\bm{\mathit{W}}, \bm{\mathit{U}}, b)$ have at most
   \begin{equation*}
   N \cdot M \cdot \max_{\substack{(i, k)\in[N]\times[M]}} \mathsf{N}_k^i(\delta) \cdot \max_{n\in[\mathsf{N}_k^i(\delta)]} L_{k,n}^i 
   \end{equation*}
   switches, where $\mathsf{N}_k^i(\delta)$ and $L_{k, n}^i$ are defined in Step 2 and Step 3 respectively.

 \label{prop: separation}
Let $T>0$ and $\mu_0^i\in\mathscr{P}(\mathbb{Q}_1^{d-1})$, $i\in[N]$, be given.
There exists $\theta\in L^\infty((0,T);\Uptheta)$ such that
\begin{equation*}
    \mathrm{conv}_g\, \mathrm{supp}(\mu^i(T))\cap \mathrm{conv}_g \,\mathrm{supp}(\mu^j(T))=\varnothing
\end{equation*}
for all $i\neq j\in[N]$, where $\mu^i \in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ denotes the unique solution to \eqref{eq: cauchy.pb}--\eqref{eq: average.vf} corresponding to $\mu_0^i$ and $\theta$. 

Furthermore, we can take $\theta$ to be piecewise constant, having $O(d\cdot N)$ switches.

 \label{lem: first.quadrant}
Let $T>0$. Suppose that $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$, for $i\in[N]$, are such that 
\begin{equation*}
    \bigcup_{i\in[N]} \mathrm{supp}(\mu^i_0)\subset\mathbb{S}^{d-1}.
\end{equation*}
Then there exists $\theta=(\bm{\mathit{W}},\bm{\mathit{U}},\bm{\mathit{B}},\bm{\mathit{V}},b)\in L^\infty((0,T);\Uptheta)$ such that 
\begin{equation*}
\mathrm{supp}(\mu^i(T)) \subset \mathbb{Q}_1^{d-1}
\end{equation*}
for all $i\in[N]$ where $\mu^i\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ denotes the unique solution to \eqref{eq: cauchy.pb} corresponding to $\mu_0^i$ and $\theta$.

Furthermore, one can take $\bm{\mathit{V}}\equiv\bm{\mathit{B}}\equiv\bm{\mathit{U}}\equiv0$, $b\equiv{\bf 1}$, and $\bm{\mathit{W}}$ piecewise constant, having at most one switch, and satisfying
\begin{equation*}
\|\bm{\mathit{W}}\|_{L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R}))}\leqslant \frac{C}{T},
\end{equation*}
where $C>0$ depends only on the supports of the measures $\mu_0^i$, $i\in[N]$.

Set $\bm{\mathit{V}}\equiv \bm{\mathit{B}}\equiv \bm{\mathit{U}}\equiv 0$ and $b\equiv{\bf 1}$.

We begin by noting that by assumption, there exists some $\omega\in\mathbb{S}^{d-1}$ with $\omega\notin\mathrm{supp}(\mu_0^i)$ for all $i\in[N]$.
Let $T_0\in(0,T)$ be chosen later on. We select 
\begin{equation*}
    \bm{\mathit{W}}(t)\equiv \bm{\mathit{W}}_1 \hspace{1cm} \text{ for } t\in[0, T_0]
\end{equation*}
where $\bm{\mathit{W}}_1$ is any $d\times d$ matrix such that
\begin{equation*}
\bm{\mathit{W}}_1 {\bf 1}=-\omega.
\end{equation*}
For this choice of parameters, the characteristics of \eqref{eq: cauchy.pb} read
\begin{equation}\label{eq:EasyCircle}
\begin{dcases}
\dot{x}(t)=\bm{\mathsf{P}}^\perp_{x(t)}(-\omega) &\text{ in }[0, T_0]\\
x(0)=x_0.
\end{dcases}
\end{equation}
For any $x_0\in\mathbb{S}^{d-1}\setminus\{\omega\}$, we observe that the solution to \eqref{eq:EasyCircle} converges to $-\omega$ in long time. Indeed,
\begin{equation}\label{eq:BasicDissipation}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t}\langle x(t), \omega\rangle=-1+\langle x(t),\omega \rangle^2<0 
\end{equation}
whenever $x(t)\in\mathbb{S}^{d-1}\backslash\{\pm\omega\}$. The solution to \eqref{eq:EasyCircle} defines a Lipschitz-continuous flow map 
$$\Phi^t\colon\mathbb{S}^{d-1}\to\mathbb{S}^{d-1},$$ 
which is independent of any measure, and which allows to write the solution $\mu^i(t,\cdot)$ to \eqref{eq: cauchy.pb} on $[0, T_0]$ as
\begin{equation*}
    \mu^i(t)=\Phi^t_\#\mu_{0}^i
\end{equation*} 
for $i\in[N]$. Since $\omega$ does not belong to the support of any of the measures $\mu_0^i$, by virtue of \eqref{eq:BasicDissipation}, we can choose $T_0>0$, depending on
\begin{equation*}
    \min_{x\in \bigcup_{i\in[N]}\mathrm{supp}(\mu_0^i)}d_g(x,\omega)
\end{equation*}
so that
\begin{equation*} 
    \max_{x\in \mathrm{supp}(\mu^i(T_0))}d_g(x,-\omega)\leqslant \frac\pi8
\end{equation*}
for all $i\in[N]$.

Let $\alpha\in\mathbb{Q}_1^{d-1}$ be such that
\begin{equation*}
  d_g(-\omega,-\alpha)>\frac\pi8.  
\end{equation*}
As a consequence, $-\alpha$ does not belong to the support of $\mu^i(T_0)$ for any $i\in[N]$. Now we choose 
\begin{equation*}
    \bm{\mathit{W}}(t)\equiv \bm{\mathit{W}}_2 \hspace{1cm} \text{ for } t\in[T_0,T]
\end{equation*} 
where $\bm{\mathit{W}}_2$ is any $d\times d$ matrix such that
\begin{equation*}
    \bm{\mathit{W}}_2{\bf 1}=\alpha.
\end{equation*}
The characteristics of \eqref{eq: cauchy.pb} in $[T_0,T]$ then read
\begin{equation*}
\begin{cases}
       \dot{x}(t)=\bm{\mathsf{P}}^\perp_{{x(t)}}(\alpha) &\text{ in }[T_0, T]\\
x(T_0)=x_0.
\end{cases}
\end{equation*}
This differential equation defines a Lipschitz-continuous flow map 
$$\Psi^{t-T_0}:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$$ 
with the same properties as in Step 1 (just replacing $-\omega$ by $\alpha$), i.e., we can choose $T>0$ large enough so that
\begin{equation*}
\mu^i(T)=\Big(\Psi^{T-T_0}\circ\Phi^{T_0}\Big)_\#\mu_{0}^i
\end{equation*}
satisfies
\begin{equation*}
    \mathrm{supp}(\mu^i(T))\subset \mathbb{Q}_1^{d-1}
\end{equation*}
for all $i\in[N]$, as desired. The bound on $\bm{\mathit{W}}$ follows by rescaling time. \qedhere

 \label{lem: induction.barycenter} 
Let $\mu_0^i\in\mathscr{P}(\mathbb{Q}_1^{d-1})$, $i\in[N]$, be given such that
    \begin{equation*}
        \mathbb{E}_{\mu_0^i}[x] \text{ is not colinear with }\mathbb{E}_{\mu_0^j}[x] \hspace{1cm} \text{ for } i\neq j.
    \end{equation*}
    Fix $j\in[N]$.
    Then for any $T>0$ and $\varepsilon>0$, and for any $\nu_0\in \mathscr{P}(\mathbb{Q}_1^{d-1})$ such that $\mathbb{E}_{\nu_0}[x]$ is colinear with $\mathbb{E}_{\mu_0^N}[x]$, there exists $\theta\in L^\infty((0,T);\Uptheta)$ such that 
    \begin{equation*}
        \mathrm{supp}(\nu(T))\cup\mathrm{supp}(\mu^j(T))\subset B\left( \frac{\mathbb{E}_{\mu^j_0}[z]}{\left\|\mathbb{E}_{\mu^j_0}[z]\right\|},\varepsilon\right),
    \end{equation*}
    and
    \begin{equation*}
        \mu^i(T)=\mu^i_0
    \end{equation*}
    for $i\neq j\in[N]$, where $\mu^i, \nu \in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ 
    denote the unique solution to \eqref{eq: cauchy.pb}--\eqref{eq: average.vf} corresponding to data $\mu_0^i$, $\nu_0$, and the parameters $\theta$.

Furthermore, one can take $\theta$ piecewise constant, having  $O(d\cdot N)$ switches.

\begin{equation*}
        \mathbb{E}_{\mu_0^i}[x] \text{ is not colinear with }\mathbb{E}_{\mu_0^j}[x] \hspace{1cm} \text{ for } i\neq j.
    \end{equation*}

\label{lem: perturbation} \label{lem: colinearity}
Let $T>0$ and let $\mu_0,\nu_0\in\mathscr{P}(\mathbb{Q}_1^{d-1})$ be two different measures such that
\begin{equation*}
        \mathbb{E}_{\mu_0}[x]= \gamma_1 \mathbb{E}_{\nu_0}[x]
    \end{equation*}
    for some $\gamma_1\in(0,1]$.
\begin{enumerate}
    \item If $\gamma_1=1$, then, setting $\bm{\mathit{V}}\equiv0$, there exist $\bm{\mathit{W}},\bm{\mathit{U}}\in\mathscr{M}_{d\times d}(\mathbb{R})$ and $b\in \mathbb{R}^d$ such that the unique solutions $\mu, \nu$ to \eqref{eq: cauchy.pb}--\eqref{eq: average.vf} corresponding to $\mu_0, \nu_0$ and these parameters, satisfy
\begin{equation*}
    \mathbb{E}_{\mu(T)}[x]\neq \mathbb{E}_{\nu(T)}[x].
\end{equation*}
Moreover the Lipschitz-continuous and invertible flow map $\Phi^T:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics of \eqref{eq: cauchy.pb}--\eqref{eq: average.vf} with these parameters satisfies
\begin{equation}\label{eq: identity.flow}
    \Phi^T(x)=x\hspace{1cm}\text{ for }x\in \mathbb{S}^{d-1}\setminus\left(\mathrm{supp}(\mu_0)\cup\mathrm{supp}(\nu_0)\right).
\end{equation}
\item If $\gamma\neq 1$, then, setting $\bm{\mathit{B}}\equiv0$, there exist $(\bm{\mathit{V}},\bm{\mathit{W}},\bm{\mathit{U}})\in L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R})^3)$ and $b\in L^\infty((0,T);\mathbb{R}^d)$,  piecewise constant with at most $2$ switches, such that the unique solutions $\mu, \nu$ to \eqref{eq: cauchy.pb}--\eqref{eq: average.vf} corresponding to data $\mu_0, \nu_0$ and these parameters satisfy
\begin{equation*}
    \mathbb{E}_{\mu(T)}[x]\neq\gamma_2\mathbb{E}_{\nu(T)}[x]
\end{equation*}
for all $\gamma_2\in\mathbb{R}$. In fact, 
\begin{align*}
  \bm{\mathit{V}}(t)&=I_d 1_{(0,T_*)}(t) &  
  \bm{\mathit{W}}(t)&=\bm{\mathit{W}} 1_{(T_*,T)}(t) \\ 
  \bm{\mathit{U}}(t)&=\bm{\mathit{U}} 1_{(T_*,T)}(t) &
  b(t)&=b 1_{(T_*,T)}(t)  
\end{align*}
for some $T_*\in (0,T)$ and $\bm{\mathit{W}}, \bm{\mathit{U}}\in \mathscr{M}_{d\times d}(\mathbb{R})$, $b\in \mathbb{R}^d$. Moreover the Lipschitz-continuous and invertible flow map $\Phi^T:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics
\begin{equation*}
\begin{cases}
    \dot{x}(t)=\bm{\mathsf{P}}^\perp_x(\bm{\mathit{W}}(t)(\bm{\mathit{U}}(t) x+b(t))_+) &\text{ in } [0,T]\\
    x(0)=x\in\mathbb{S}^{d-1},
\end{cases}    
\end{equation*}
satisfies
\begin{equation*}
  \Phi^T(x)=x\hspace{1cm} \text{ for all }x\notin \mathrm{conv}_g\, \mathrm{supp}(\mu_0)\cup \mathrm{conv}_g\, \mathrm{supp}(\nu_0).
\end{equation*}
\end{enumerate}

We argue by induction over $N$. The base case $N=1$ is trivially satisfied. Assume that 
\begin{equation}\label{eq: empty.inter.sup}
\mathrm{conv}_g\,\mathrm{supp}(\mu^i_0)\cap\mathrm{conv}_g\,\mathrm{supp}(\mu^j_0)=\varnothing \hspace{1cm} \text{ for } i\neq j\in[N-1],
\end{equation}
and let $\mu_0^N\in \mathscr{P}(\mathbb{Q}_1^{d-1})$ be arbitrary. 
We prove that there exist parameters $\theta$ as in the statement, such that the solution $\mu^i$ to \eqref{eq: cauchy.pb} satisfies
\begin{equation*}
\mathrm{supp}(\mu^i(T))\cap\mathrm{supp}(\mu^j(T))=\varnothing\hspace{1cm} \text{ for } i\neq j\in[N].
\end{equation*}
Since $\mathrm{supp}(\mu^i_0)\subset\mathbb{Q}_1^{d-1}$, \eqref{eq: empty.inter.sup} implies that
\begin{equation*}
    \mathbb{E}_{\mu^i_0}[x]\text{ is not colinear with }\mathbb{E}_{\mu^j_0}[x] \hspace{1cm} \text{ for } i\neq j\in[N-1].
\end{equation*}
Now if $\mathbb{E}_{\mu_0^N}[x]$ is not colinear with $\mathbb{E}_{\mu_0^i}[x]$ for all $i\in[N-1]$, one can conclude by a simple application of \Cref{lem: induction.barycenter}. 
On another hand, as a consequence of \eqref{eq: empty.inter.sup}, $\mathbb{E}_{\mu^N_0}[x]$ is colinear with $\mathbb{E}_{\mu^i_0}[x]$ for at most one $i\in[N-1]$. 
Suppose that this is the case, and without loss of generality, we label this index $i=N-1$. We now proceed as follows.
\begin{enumerate}
    \item In $\left[0,T/4\right]$, we apply \Cref{lem: induction.barycenter}, with $\varepsilon>0$ small enough, to guarantee the existence of piecewise constant $\theta_1\in L^\infty((0,T/4); \Uptheta)$ having $O(d\cdot N)$ switches, such that the solution to \eqref{eq: cauchy.pb} satisfies
\begin{align}
    \mathrm{supp}\left(\mu^j\left(\frac{T}{4}\right)\right)\cap \mathrm{supp}\left(\mu^N\left(\frac{T}{4}\right)\right)=\varnothing\label{eq: first.step}\\
    \mathrm{supp}\left(\mu^j\left(\frac{T}{4}\right)\right)\cap \mathrm{supp}\left(\mu^{N-1}\left(\frac{T}{4}\right)\right)=\varnothing\nonumber
\end{align}
  for all $j\in[N-2]$.
\item In $\left[T/4,T/2\right]$, we apply the first part of \Cref{lem: perturbation} to find constant $\theta_2$ such that 
\begin{equation*}
    \mathbb{E}_{\mu^{N-1}\left(\frac{T}{2}\right)}[x]\neq \mathbb{E}_{\mu^{N}\left(\frac{T}{2}\right)}[x],
\end{equation*}
whereas, thanks to \eqref{eq: identity.flow} and the Lipschitz character of the ODE,
\begin{equation*}
    \mathrm{supp}\left(\mu^j\left(\frac{T}{2}\right)\right)\cap \mathrm{supp}\left(\mu^{N-1}\left(\frac{T}{2}\right)\right)=\varnothing
\end{equation*}
for all $j\in[N-2]$.
\item 
In $[T/2,3T/4]$, we apply the second part of \Cref{lem: colinearity} to $\mu^{N-1}\left(T/2\right)$ and $\mu^{N}\left(T/2\right)$ so that there are some piecewise constant $\theta_3\in L^\infty((T/2,3T/4);\Uptheta)$ such that 
\begin{equation*}
    \mathbb{E}_{\mu^N\left(\frac{3T}{4}\right)}[x] \text{ is not colinear with } \mathbb{E}_{\mu^{N-1}\left(\frac{3T}{4}\right)}[x].
\end{equation*}
Furthermore, owing to \eqref{eq: first.step}, and noting that $\bm{\mathit{V}}=I_d$ in \Cref{lem: perturbation}, along with \eqref{eq: set.inclusion}, we also have  
\begin{equation*}
    \mathrm{supp}\left(\mu^i\left(\frac{3T}{4}\right)\right)\cap\mathrm{supp}\left(\mu^j\left(\frac{3T}{4}\right)\right)=\varnothing
\end{equation*}
for all $i\neq j\in[N-1]$, and for all $i\in[N-2]$ and $j=N$. 
\item The assumption of \Cref{lem: induction.barycenter} is now fulfilled by all $N$ measures, so by picking $\varepsilon>0$ small enough and applying \Cref{lem: induction.barycenter} once again, this time in $\left[3T/4,T\right]$, the conclusion follows.\qedhere
\end{enumerate}

\begin{equation*}
    \mathbb{E}_{\mu^i_0}[x]\text{ is not colinear with }\mathbb{E}_{\mu^j_0}[x] \hspace{1cm} \text{ for } i\neq j\in[N-1].
\end{equation*}

 \label{prop: interpolation.neural.ode}
Suppose $d\geqslant3$. Consider 
\begin{equation*} \tag{$\mathscr{D}$}
  \left(x_0^i,y^i\right)\in\mathbb{S}^{d-1}\times\mathbb{S}^{d-1} \hspace{1cm} \text{ for } i\in[M], 
\end{equation*}
with $x_0^i\neq x_0^j$ and $y^i\neq y^j$ for $i\neq j$, and suppose that for any $i\in[M]$, there exist $\gamma_i\in\mathbb{S}^{d-1}$ and $\varepsilon_i>0$ such that
\begin{equation*} 
\left\langle\gamma_i,x_0^i-y^i\right\rangle=0 \hspace{1cm} \text{ and } \hspace{1cm} 
x_0^j\notin H_{\varepsilon_i}^{\gamma_i}
\end{equation*}
for $j\neq i\in[N]$, where
\begin{equation*}
H_{\varepsilon_i}^{\gamma_i}:=\Big\{x\in \mathbb{S}^{d-1}\colon|\langle x,\gamma_i\rangle|\leqslant \varepsilon_i\Big\}.
\end{equation*}
Then for any $T>0$, there exists $\theta=(\bm{\mathit{W}},\bm{\mathit{U}},b)\in L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d)$, piecewise constant having at most $6M$ switches, such that for any $i\in[M]$, the solution $x^i(\cdot)\in \mathscr{C}^0([0,T];\mathbb{S}^{d-1})$ to
\begin{equation} \label{eq: neural.ode.sphere}
\begin{cases}
\dot{x}^i(t)=\bm{\mathsf{P}}^\perp_x\left(\bm{\mathit{W}}(t)\Big(\bm{\mathit{U}}(t)x^i(t)+b(t)\Big)_+\right) &\text{ in } [0, T]\\
x^i(0)=x_0^i,
\end{cases}
\end{equation}
satisfies 
$$x^i(T)=y^i.$$
Moreover there exists some $C>0$, not depending on $\mathscr{D}$ nor $T$, such that
\begin{equation*}
\|\theta\|_{L^\infty((0,T);\Uptheta)}\leqslant \frac{C\cdot M}{\displaystyle T\min_{i\in[M]}\varepsilon_{i}}.
\end{equation*}

 \label{lem: induction.neural.ode}
Suppose $d\geqslant3$. Consider 
\begin{equation*} \tag{$\mathscr{D}$}
  \left(x_0^i,y^i\right)\in\mathbb{S}^{d-1}\times\mathbb{S}^{d-1} \hspace{1cm} \text{ for } i\in[M], 
\end{equation*}
with $x_0^i\neq x_0^j$ and $y^i\neq y^j$ for $i\neq j$, with $x_0^i=y^i$ for $i\in[M-1]$, and suppose that there exist $\gamma\in\mathbb{S}^{d-1}$ and $\varepsilon>0$ such that
\begin{equation*} 
\left\langle\gamma,x_0^M-y^M\right\rangle=0 \hspace{1cm} \text{ and } \hspace{1cm} 
x_0^i\notin H_{\varepsilon}^{\gamma}
\end{equation*}
for all $i\in[M-1]$. 
Then, for every $T>0$, there exist piecewise constant parameters $\theta=(\bm{\mathit{W}},\bm{\mathit{U}},b)\in L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d)$, all having at most $6$ switches, such that for any $i\in[M]$, the solution $x^i(\cdot)\in \mathscr{C}^0([0,T];\mathbb{S}^{d-1})$ to \eqref{eq: neural.ode.sphere} satisfies
\begin{equation*}
x^i(T)=y^i.
\end{equation*}
Moreover, there exists some constant $C>0$, not depending on $\mathscr{D}$ and $T$, such that
    \begin{equation*}
        \|\theta\|_{L^\infty((0,T); \Uptheta)}\leqslant \frac{C}{T\cdot\varepsilon}.
    \end{equation*}

The final parameters take the form
\begin{align*}
    \bm{\mathit{W}}(t) &= \sum_{j=1}^6 \bm{\mathit{W}}_j 1_{\left[\frac{(j-1)T}{6},\frac{jT}{6}\right]}(t),\\
    \bm{\mathit{U}}(t) &= \sum_{j=1}^6 \bm{\mathit{U}}_j 1_{\left[\frac{(j-1)T}{6},\frac{jT}{6}\right]}(t),\\
    b(t) &= \sum_{j=1}^6 b_j 1_{\left[\frac{(j-1)T}{6},\frac{jT}{6}\right]}(t),
\end{align*}
where 
\begin{align*}
  \bm{\mathit{W}}_5 &= -\bm{\mathit{W}}_1 & \bm{\mathit{U}}_5 &= \bm{\mathit{U}}_1 & b_5 &= b_1, \\
  \bm{\mathit{W}}_6 &= -\bm{\mathit{W}}_2 & \bm{\mathit{U}}_6 &= \bm{\mathit{U}}_2 & b_6 &= b_2, \\
         &         & \bm{\mathit{U}}_3 &= \bm{\mathit{U}}_4 & b_3 &= b_4.
\end{align*}
Throughout, the time \( T > 0 \) is adjusted later by rescaling the norm of the parameters.




\subsubsection*{Step 1. The anchor points}
In this step we find three anchor points which serve to build the parameters in what follows. 
Since $\langle \gamma, x_0^M-y^M\rangle=0$, we can find some $\omega\in\mathbb{S}^{d-1}$ such that 
\begin{equation}\label{eq: great.circle.hyperplane}
\langle \gamma, \omega\rangle=0,
\end{equation}
as well as
\begin{equation}\label{eq: omega.distance}
d_g\left(\omega, x_0^M\right)\geqslant \frac{\pi}{2},\hspace{1cm}\text{ and } \hspace{1cm}  d_g\left(\omega, y^M\right)\geqslant\frac{\pi}{2}.
\end{equation}
Because of \eqref{eq: great.circle.hyperplane}, we consider the point $\omega_+$ lying on the minimizing geodesic between $\omega$ and $\gamma$, satisfying
\begin{equation*}
d_g(\omega_+,\omega)=\frac{\pi}{8}.
\end{equation*}
Similarly, we consider the point $\omega_-$ lying on the minimizing geodesic between $\omega$ and $-\gamma$, satisfying 
\begin{equation*}
d_g(\omega_-,\omega)=\frac{\pi}{8}.
\end{equation*}
We have 
\begin{align*}
d_g\left(\omega_+,x_0^M\right)&\geqslant d_g\left(\omega,x_0^M\right)-d_g\left(\omega,\omega_+\right)=\frac{3\pi}{8},\\
d_g\left(\omega_+,y^M\right)&\geqslant \frac{3\pi}{8},\\ 
d_g\left(\omega_-,x_0^M\right)&\geqslant \frac{3\pi}{8},\\
d_g\left(\omega_-,y^M\right)&\geqslant \frac{3\pi}{8}.
\end{align*}
As a consequence, the hyperplane 
\begin{equation*}
\left\{x\in\mathbb{S}^{d-1}\colon\langle\omega,x\rangle=\cos\left(\frac{\pi}{8}+\tau\right)\right\}
\end{equation*}
is a separating hyperplane for the ball $B\left(\omega,\frac{\pi}{8}+\tau\right)$ and the points $x_0^M$ and $y^M$ for every $\tau\in(0,\frac{3\pi}{8})$; namely
\begin{equation*}
\left\langle \omega,x_0^M\right\rangle -\cos\left(\frac{\pi}{8}+\tau\right)=\cos d_g\left(\omega,x_0^M\right)-\cos\left(\frac{\pi}{8}+\tau\right)<0,
\end{equation*}
where the inequality is by virtue of \eqref{eq: omega.distance}. 
Analogous computations hold for $y^M$, whereas
\begin{equation*}
\langle\omega,x\rangle -\cos\left(\frac{\pi}{8}+\tau\right)>0
\end{equation*}
for all $x\in B(\omega,\frac{\pi}{8}+\frac{1}{2}\tau)$ and $\tau\in(0,\frac{3\pi}{8})$ (see \Cref{fig: setup.ball}).

