\subsubsection*{Step 2. Isolating $x_0^M$ and $y^M$} 
Let 
$$\epsilon:=\min\left\{\varepsilon,\frac{\pi}{4}\right\}.$$ 
Consider 
\begin{equation*}
 \bm{\mathit{U}}_1=\gamma {\bf1}^\top \hspace{1cm} \text{ and } \hspace{1cm}   b_1=-\frac{\epsilon}{2}{\bf1}. 
\end{equation*}
Then
\begin{equation*}
\left(\bm{\mathit{U}}_1x+b_1\right)_+=\left(\langle \gamma, x\rangle -\frac{\epsilon}{2}  \right)_+{\bf1}.
\end{equation*}
Choose any $\bm{\mathit{W}}_1$ so that
\begin{equation*}
\bm{\mathit{W}}_1{\bf1}=\omega_+.
\end{equation*}
Define
\begin{equation*}
\mathscr{S}_+:=\left\{ x\in \mathbb{S}^{d-1}:\langle \gamma, x\rangle \geqslant \epsilon\right\}.
\end{equation*}
Obviously $\omega_+\in \mathscr{S}_+$. 
Observe that the trajectories of the ODE
\begin{equation} \label{eq: neural.ode.separation}
\dot{x}(t)=\left(\langle \gamma, x(t)\rangle -\frac{\epsilon}{2}\right)_+\bm{\mathsf{P}}^\perp_{x(t)}(\omega_+)\hspace{1cm}\text{ for $t\geqslant0$,}
\end{equation}
follow the Riemannian gradient flow of the distance between $\omega_+$ and $x$ in $\mathscr{S}_+$. Indeed,
\begin{equation*}
     \nabla_1 d_g(x,\omega_+)=-\frac{\bm{\mathsf{P}}^\perp_x(\omega_+)}{\sqrt{1-\langle x,\omega_+\rangle^2 }}.
\end{equation*}
Then, setting $f(x)=\left(\langle \gamma, x\rangle -\frac{\epsilon}{2}\right)_+$, we have
 \begin{align*}
    \dot{x}(t)&=-f(x(t))\,\sqrt{1-\langle x(t),\omega_+\rangle^2 } \,\nabla_1 d_g(x(t),\omega_+)\nonumber\\
    &=-\overline{f}(x(t))\,\nabla_1 d_g(x(t),\omega_+).
 \end{align*}
 Since $\overline{f}$ is a nonnegative scalar function, by appropriately reparameterizing time, we conclude that $x(t)$ follows the desired gradient flow.
 In turn, the trajectory $x(t)$ of \eqref{eq: neural.ode.separation} starting from any $x_0\in\mathscr{S}_+$ always lies on the minimal geodesic from $x_0$ to $\omega_+\in\mathscr{S}_+$. Since $\mathscr{S}_+$ is geodesically convex, we gather that $x(t)\in\mathscr{S}_+$ for all $t\geqslant0$. Then, notice that 
 \begin{equation*}
     \overline{f}(x)=0 \qquad \Longleftrightarrow \qquad x=\omega_+ \quad \text{ or } \quad x\in  \left\{y\in\mathbb{S}^{d-1}:\langle \gamma,y\rangle\leqslant \frac{\epsilon}{2}\right\}.
 \end{equation*}
 Thus, unless $x(t)=\omega_+$, $\overline{f}$ is uniformly bounded from below on $\mathscr{S}_+$, and since 
 \begin{equation*}
     \nabla_1 d_g(x,\omega_+)=0 \qquad \Longleftrightarrow \qquad x=\pm \omega_+,
 \end{equation*}
 we can conclude that $x(t)\to\omega_+$ as $t\to+\infty$ for any $x_0\in\mathscr{S}_+$ by applying the LaSalle invariance principle \cite{lasalle1960some}.

















For any $x_0\in\mathbb{S}^{d-1}$, set
\begin{equation*}
T_{\frac{\pi}{16}}(x_0):=\inf\left\{t\geqslant 0:\quad x(t)\in B\left(\omega_+,\frac{\pi}{16}\right)\right\},
\end{equation*}
where $x(\cdot)$ is the solution to the Cauchy problem for \eqref{eq: neural.ode.separation} with data $x_0$. 
Since $\|\gamma\|=1$, $\|\bm{\mathit{W}}_1\|_{\text{op}}\leqslant1$ and $\|b_1\|\leqslant\frac{\epsilon}{2}\sqrt{d}$, bounding the $L^\infty$--norm of the parameters comes from bounding $T_{\frac{\pi}{16}}(x_0)$ uniformly over $x_0\in\mathscr{S}_+$ and rescaling time. 
For every $x_0\in B\left(\omega_+,\frac{\pi}{16}\right)$ we see that $T_{\frac{\pi}{16}}(x_0)$ is trivially $0$, whereas for  $x_0\in \mathscr{S}_+\setminus B\left(\omega_+,\frac{\pi}{16}\right)$ one has
\begin{align} \label{eq: estimate.neural}
\frac{\, \mathrm{d}}{\, \mathrm{d} t} \langle x(t),\omega_+\rangle&=\left( \langle \gamma, x(t)\rangle-\frac{\epsilon}{2}\right)_+\left(1-\langle \omega_+,x\rangle^2\right)\nonumber\\
&\geqslant \frac{\epsilon}{2}\left(1-\langle \omega_+,x\rangle^2\right)\nonumber\\
&\geqslant \frac{\epsilon}{2}\left(1-\cos^2\left(\frac{\pi}{16}\right)\right).
\end{align}
Hence $T_{\frac{\pi}{16}}(x_0)=O(1/\epsilon)$ for all $x_0\in \mathscr{S}_+$.  

Finally, by following the same arguments leading to \eqref{eq: estimate.neural}, beyond some large enough time, and for every $x_0\in \mathscr{S}_+$, we can apply the Hartman-Grobman theorem \cite{hartman1960lemma, hartman1963local, shub2013global}: the behavior near the critical point $\omega_+$ is governed\footnote{Note that the critical point $\omega_+$ is hyperbolic since we are working in $\mathsf{T}_{\omega_+}\mathbb{S}^{d-1}$. On $\mathbb{R}^d$, there is a zero eigenvalue associated to the radial direction.} by the linearized system 
 \begin{equation*}
 \begin{cases}
     \dot{y}(t)=-\left(\langle \gamma,\omega_+\rangle-\displaystyle\frac{\epsilon}{2}\right)y(t) & \text{ in } \mathbb{R}_{\geqslant0}\\
     y(0)=y_0\in \mathsf{T}_{\omega_+}\mathbb{S}^{d-1},
     \end{cases}
 \end{equation*}
 which is exponentially stable. Thus, by the Hartman-Grobman theorem, for all $x_0\in\mathscr{S}_+$,
 \begin{equation}\label{eq: Hartman.Grobman}
     d_g(x(t),\omega_+)\leqslant Ke^{-\lambda t} \hspace{1cm} \text{  for all } t\geqslant 0, 
 \end{equation}
and for some $\lambda>0$ and $K\geqslant 1$ which depend on $x_0$, $\epsilon$ and $\gamma$ only.

Similarly, consider 
\begin{equation*}
 \bm{\mathit{U}}_2=-\gamma {\bf1}^\top \hspace{1cm} \text{ and } \hspace{1cm}   b_2=-\frac{\epsilon}{2}{\bf1}.
\end{equation*}
Then, 
\begin{equation*}
(\bm{\mathit{U}}_2x+b_2)_+=\left( \langle -\gamma, x\rangle -\frac{\epsilon}{2}\right)_+ {\bf1}.
\end{equation*}
Choose any $\bm{\mathit{W}}_2$ so that
\begin{equation*}
\bm{\mathit{W}}_2{\bf1}=\omega_-.
\end{equation*}
Define
\begin{equation*}
\mathscr{S}_-:=\left\{ x\in \mathbb{S}^{d-1}:    \langle -\gamma, x\rangle \geqslant \epsilon\right\}.
\end{equation*}
After reasoning similarly for $\mathscr{S}_-$ as for $\mathscr{S}_+$, and by rescaling time so that
\begin{equation*}
\|\bm{\mathit{W}}_1\|_{\text{op}} = O\left( \frac{1}{T\cdot\epsilon}\right), \qquad \|\bm{\mathit{W}}_2\|_{\text{op}}=O\left( \frac{1}{T\cdot\epsilon}\right),
\end{equation*}
we deduce that for any $T>0$ there exists $\theta_1\in L^\infty((0,T/3);\mathscr{M}_{d\times d}(\mathbb{R})^2\times \mathbb{R}^d)$, piecewise constant having two switches, such that the associated flow map of \eqref{eq: neural.ode.sphere} is a Lipschitz-continuous and invertible map that satisfies
\begin{align}\label{eq: sphere.separation}
&\Phi^{\frac{T}{3}}_{\theta_1}(x_0^i)\in B\left(\omega,\frac{3\pi}{16}\right)\\
&\Phi^{\frac{T}{3}}_{\theta_1}(x)=x\hspace{1cm}\text{ if }x\in H_\epsilon^\gamma\nonumber.
\end{align}

