\subsubsection*{Step 3. Steering $x_0^M$ to $y^M$}




By virtue of \eqref{eq: sphere.separation}, the hyperplane
\begin{equation*}
\left\{x\in\mathbb{S}^{d-1}\colon\langle \omega, x\rangle =\cos\left(\frac{3\pi}{16}\right)\right\}
\end{equation*}
is a separating hyperplane: it separates $x_0^N$ and $y^N$ from $\Phi_{\theta_1}^{\frac{T}{3}}(x_0^i)$ for $i\in[M-1]$. Consider
\begin{align*}
\bm{\mathit{U}}_3=-\omega {\bf1}^\top, \hspace{1cm} \text{ and } \hspace{1cm}
b_3=\cos\left(\frac{3\pi}{16}\right){\bf1}.
\end{align*}
With this choice, we have 
\begin{align*}
    \left( \bm{\mathit{U}}_3x+b_3 \right)_+=0 \hspace{1cm} \text{ for } &x\in B\left(\omega, \frac{3\pi}{16}\right),\\
    \left( \bm{\mathit{U}}_3x+b_3 \right)_+= \underbrace{\left(\langle -\omega, x\rangle+\cos\left(\frac{3\pi}{16}\right)\right)}_{>0} {\bf1} \hspace{1cm} \text{ for } &x\in \mathbb{S}^{d-1}\setminus B\left(\omega, \frac{3\pi}{16}\right).
\end{align*}
Take two points $z_1,z_2\in \mathbb{S}^{d-1}\setminus B\left(\omega, \frac{3\pi}{16}\right)$ such that
\begin{enumerate}
    \item $\{c(s)\}_{s\in[0,1]}$ is a geodesic satisfying $c(0)=x_0^M$ and $c(1)=z_2$;
    \item $c(1-s_0)=y^M$ for some $s_0\in(0,1)$;
    \item $c(s_{z_1})=z_1$ for some $s_{z_1}\in(0,1-s_0)$;
    \item $\{c(s)\}_{s\in[0,1]}\subset \mathbb{S}^{d-1}\setminus B\left(\omega, \frac{3\pi}{16}\right)$;
    \item $d_g(z_1,x_0^M)\leqslant \kappa\pi$ and $d_g(z_1,z_2)\leqslant \kappa\pi$ for some\footnote{can be chosen as such because $\{c(s)\}_{s\in[0,1]}\subset \mathbb{S}^{d-1}\setminus B\left(\omega,\frac{3\pi}{16}\right)$---indeed, take $\kappa=\frac{29}{32}$.} $\kappa<1$.
\end{enumerate}
Consider any $d\times d$ matrix $\bm{\mathit{W}}_3$ such that
\begin{equation*}
\bm{\mathit{W}}_3{\bf1}=z_1.
\end{equation*}
The Cauchy problem \eqref{eq: neural.ode.sphere} with these parameters, for the $i=M$-th particle, reads
\begin{equation}\label{eq: neural.ode.step3}
\begin{cases}
\dot{x}(t)=\left(\langle -\omega, x(t)\rangle+\cos\left(\frac{3\pi}{16}\right)\right)_+\bm{\mathsf{P}}^\perp_{x(t)}(z_1) &\text{ on } \mathbb{R}_{\geqslant0}\\
x(0)=x_0^M.
\end{cases}
\end{equation}
Since $d_g(x_0^M,z_1)\leqslant\kappa\pi$, and since the minimizing geodesic between $x_0^M$ and $z_1$ is contained in $\{c(s)\}_{s\in [0,1]}\subset B(\omega, \frac{3\pi}{16})$, we gather that there exists some large enough time $\tau>0$ such that
\begin{equation} \label{eq: geodesic.toll}
    d_g\left( x(\tau),z_2\right)\leqslant d_g\left( x(\tau),z_1\right)+d_g\left( z_1,z_2\right)\lesssim e^{-\lambda\tau}+\kappa\pi\leqslant\kappa_2\pi
\end{equation}
for some $\kappa_2<1$ and $\lambda>0$. This comes from the long-time convergence of \eqref{eq: neural.ode.step3} to $z_1$, which can be shown by following the same arguments as for \eqref{eq: Hartman.Grobman}, replacing $\omega_+$ by $z_1$. 
For any $d\times d$ matrix $\bm{\mathit{W}}_4$ such that
\begin{equation*}
\bm{\mathit{W}}_4{\bf1}=z_2,
\end{equation*}
the Cauchy problem \eqref{eq: neural.ode.sphere}, for the $i=M$-th particle, reads
\begin{equation} \label{eq: neural.ode.step3.2}
\begin{cases}
\dot{x}(t)=\left(\langle -\omega, x(t)\rangle+\cos\left(\frac{3\pi}{16}\right)\right)_+\bm{\mathsf{P}}^\perp_{x(t)}(z_2) &\text{ for } t\geqslant\tau\\
x(\tau) = x(\tau)
\end{cases}
\end{equation}
where $x(\tau)$ is the solution of \eqref{eq: neural.ode.step3} at $t=\tau$. Since $d_g(z_1,z_2)\leqslant \kappa \pi$, $y^M$ lies on the minimizing geodesic between $x(\tau)$ and $z_2$. All the while, thanks to \eqref{eq: geodesic.toll}, taking $T$ even larger than before, we deduce that that the solution to \eqref{eq: neural.ode.step3.2} satisfies
\begin{equation*}
    x(T)=y^M.
\end{equation*}
Therefore, as in the previous step, we deduce that for any $T>0$ there exists some $\theta_2\in L^\infty((T/3,2T/3);\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d)$, piecewise constant having two switches, such that the associated flow map of \eqref{eq: neural.ode.sphere} is a Lipschitz-continuous and invertible map that satisfies
\begin{align*}
\Phi^{\frac{2T}{3}}_{\theta_2}(x)&=x\hspace{1cm}\text{ if }x\in B\left(\omega, \frac{3\pi}{16}\right),\\
\Phi^{\frac{2T}{3}}_{\theta_2}(x_0^M)&=y^M,
\end{align*}
and
\begin{equation*}
    \left(\Phi_{\theta_2}^{\frac{2T}{3}}\circ\Phi_{\theta_1}^{\frac{T}{3}}\right)(x_0^i)= \Phi_{\theta_1}^{\frac{T}{3}}(x_0^i)\in B\left(\omega, \frac{3\pi}{16}\right)\qquad\text{ for } i\in[M-1]
\end{equation*}
as well as
\begin{equation*}
    \left(\Phi_{\theta_2}^{\frac{2T}{3}}\circ\Phi_{\theta_1}^{\frac{T}{3}}\right)(x_0^M)= \Phi_{\theta_2}^{\frac{2T}{3}}(x_0^M)=y^M.
\end{equation*}


\subsubsection*{Step 4. Bringing $x^i(T)$ back to $y^i$}
We conclude by applying the inverse of the flow map $\Phi^{\frac{T}{3}}_{\theta_1}$: defining
\begin{equation*}
    \Phi^T_{\text{fin}}:=\left(\Phi^{\frac{T}{3}}_{\theta_1}\right)^{-1}\circ \Phi^{\frac{2T}{3}}_{\theta_2} \circ\Phi^{\frac{T}{3}}_{\theta_1},
\end{equation*}
we have $\Phi^T_{\text{fin}}(x_0^i)=y^i$ for all $i\in[M]$, as desired.

\begin{align*}
  \bm{\mathit{W}}_5 &= -\bm{\mathit{W}}_1 & \bm{\mathit{U}}_5 &= \bm{\mathit{U}}_1 & b_5 &= b_1, \\
  \bm{\mathit{W}}_6 &= -\bm{\mathit{W}}_2 & \bm{\mathit{U}}_6 &= \bm{\mathit{U}}_2 & b_6 &= b_2, \\
         &         & \bm{\mathit{U}}_3 &= \bm{\mathit{U}}_4 & b_3 &= b_4.
\end{align*}

\begin{equation}\label{eq: omega.distance}
d_g\left(\omega, x_0^M\right)\geqslant \frac{\pi}{2},\hspace{1cm}\text{ and } \hspace{1cm}  d_g\left(\omega, y^M\right)\geqslant\frac{\pi}{2}.
\end{equation}

\begin{equation}\label{eq: Hartman.Grobman}
     d_g(x(t),\omega_+)\leqslant Ke^{-\lambda t} \hspace{1cm} \text{  for all } t\geqslant 0, 
 \end{equation}

\begin{equation} \label{eq: geodesic.toll}
    d_g\left( x(\tau),z_2\right)\leqslant d_g\left( x(\tau),z_1\right)+d_g\left( z_1,z_2\right)\lesssim e^{-\lambda\tau}+\kappa\pi\leqslant\kappa_2\pi
\end{equation}

\Cref{prop: compression} yields a flow map that clusters the support of the input measure, which in turn allows to reduce a universal approximation property of maps in $L^p(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$ to interpolation via flow maps  proved in \Cref{prop: interpolation.neural.ode}. 
Indeed it suffices to consider a simple function $\varphi:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ defined as
\begin{equation*}
\varphi(x)=\sum_{i=1}^N y_i1_{\Omega_i}(x)
\end{equation*}
with $y_i\in \mathbb{S}^{d-1}$. Universal approximation in $L^p(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$, $p<+\infty$, is equivalent to the $\mathsf{W}_p$-approximate interpolation of
\begin{equation*}
\, \mathrm{d}\mu_0^i(x)=1 _{\Omega_i}(x)\, \mathrm{d} x,\quad
\mu_1^i=|\Omega_i|\updelta_{y_i}
\end{equation*}
for $i\in[N]$. Note that, by construction, the supports of $\mu_0^i$ (and of $\mu_1^i$) are pairwise disjoint. Thus the attention component of the vector field is not needed to perform this task. This is generalized in the next section.

\label{lem: hyp.propagation}
Suppose that for every $i\in[N]$ there exists $\mathsf{T}^i\in L^2(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$ such that
\begin{equation} \label{eq: hypothesis}
    \mathsf{T}^i_\#\mu_0^i=\mu_1^i.
\end{equation}
Consider the flow map $\Phi_1:\mathscr{P}(\mathbb{S}^{d-1})\to\mathscr{P}(\mathbb{S}^{d-1})$ (respectively $\Phi_3$) given by \Cref{prop: separation} with data $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$ (respectively $\mu_1^i\in\mathscr{P}(\mathbb{S}^{d-1})$) for $i\in[N]$. 
Then, there exists a Lipschitz-continuous and invertible map $\Psi:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ such that
\begin{equation} \label{eq: diffeo.supports}
\Psi\big|_{\mathrm{supp}\left(\Phi_1(\mu_0^i)\right)}=\Psi^i
\end{equation}
for any $i\in[N]$, where $\Psi^i:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ is another Lipschitz-continuous and invertible map that satisfies
\begin{equation*}
\left(\Psi^i\circ \mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i= \left(\Psi\circ \mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i=\left(\mathsf{T}^i_{\Phi_3}\right)_\#\mu_1^i=\Phi_3(\mu_1^i)
\end{equation*}
for some Lipschitz-continuous and invertible maps $\mathsf{T}_{\Phi_1}^i, \mathsf{T}_{\Phi_3}^i:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$.

\label{lem: monge}
Suppose $\mu\in \mathscr{P}(\mathbb{S}^{d-1})$ and $\mathsf{T}^1,\mathsf{T}^2:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ measurable, with $\mathsf{T}^1$ bijective. Then
\begin{equation} \label{eq: linearized.wasserstein}
\mathsf{W}_2\left(\mathsf{T}^1_\#\mu,\mathsf{T}^2_\#\mu\right)\lesssim\left\|\mathsf{T}^1-\mathsf{T}^2\right\|_{L^2(\mu)}.
\end{equation}

Since $\mathsf{T}^1$ is bijective, there is a measurable $\Psi:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ such that
\begin{equation*}
\Psi(\mathsf{T}^1(x))=\mathsf{T}^2(x) \hspace{1cm} \text{ for all } x\in\mathbb{S}^{d-1}. 
\end{equation*}
Then
\begin{equation*}
\mathsf{W}_2^2\left(\mathsf{T}^1_\#\mu,\mathsf{T}^2_\#\mu\right)\lesssim\int\|x-\Psi(x)\|^2\left(\mathsf{T}^1_\#\mu\right)(\, \mathrm{d} x)=\left\|\mathsf{T}^1-\mathsf{T}^2\right\|_{L^2(\mu)}^2.\qedhere
\end{equation*}

 \label{lem: univ.approx}
Suppose $\varepsilon>0$ and $\mu\in \mathscr{P}(\mathbb{S}^{d-1})$. 
For every $\Psi\in L^2(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$, there exists a Lipschitz-continuous and invertible map $\Psi_\varepsilon:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the solution map of \eqref{eq: neural.pde.sphere}, namely 
$$\Phi^T_{\theta_\varepsilon}(\mu)=(\Psi_\varepsilon)_\#\mu$$ for some piecewise constant $\theta_\varepsilon\in L^\infty((0,T);\Uptheta)$ with finitely many switches, such that
\begin{equation*}
\left\|\Psi-\Psi_\varepsilon\right\|_{L^2(\mu)}\leqslant\varepsilon.
\end{equation*}

We split the proof in three steps.

\subsubsection*{Step 1. Disentanglement} 

We begin by rendering the supports of the initial measures $(\mu_0^i)_{i\in[N]}$ (respectively, the target measures $(\mu_1^i)_{i\in[N]}$) pairwise disjoint by virtue of applying \Cref{prop: separation} to \eqref{eq: cauchy.pb} with data $\mu_0^i$ at time $t=0$ (respectively $\mu_1^i$ at time $t=2T/3$) for any $i\in[N]$. 
This entails the existence of two parameterized flow maps
\begin{equation*}
    \Phi_{\theta_1}^{t}:\mathscr{P}(\mathbb{S}^{d-1})\mapsto \mathscr{P}(\mathbb{S}^{d-1})
\end{equation*}
for $t\in[0,T/3]$, and
\begin{equation*}
    \Phi_{\theta_3}^{t}:\mathscr{P}(\mathbb{S}^{d-1})\mapsto \mathscr{P}(\mathbb{S}^{d-1})
\end{equation*}
for $t\in[2T/3, T]$, induced by \eqref{eq: cauchy.pb}, which are such that
\begin{equation*}
    \mathrm{supp}\left(\Phi_{\theta_1}^{\frac{T}{3}}(\mu_0^i)\right)\cap \mathrm{supp}\left(\Phi_{\theta_1}^{\frac{T}{3}}(\mu_0^j)\right)=\varnothing\hspace{1cm}\text{ if }i\neq j,
\end{equation*}
and 
\begin{equation*}
    \mathrm{supp}\left(\Phi_{\theta_3}^{T}(\mu_1^i)\right)\cap \mathrm{supp}\left(\Phi_{\theta_3}^{T}(\mu_1^j)\right)=\varnothing\hspace{1cm}\text{ if }i\neq j.
\end{equation*}
Since \eqref{eq: cauchy.pb} is well-posed and time-reversible, 
we further gather that there exists some constant $C=C(T,\theta_3)>0$ such that
\begin{equation} \label{eq: continuity.inverse.flow}
\mathsf{W}_2\left(\left(\Phi_{\theta_3}^{T}\right)^{-1}(\mu),\left(\Phi_{\theta_3}^{T}\right)^{-1}(\nu)\right)\leqslant C\cdot\mathsf{W}_{2}(\mu,\nu)
\end{equation}
holds for any $\mu,\nu\in \mathscr{P}(\mathbb{S}^{d-1})$.


\subsubsection*{Step 2. Matching}


By virtue of \Cref{lem: hyp.propagation}, there exists a Lipschitz-continuous and invertible map $\Psi:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ such that 
\begin{equation*}
    \Psi\Big|_{\mathrm{supp}\left(\Phi^{\frac{T}{3}}_{\theta_1}(\mu_0^i)\right)}=\Psi^i,
\end{equation*}
for $i\in[N]$ where $\Psi^i:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ satisfies 
\begin{equation} \label{eq: first.psi}
    \Psi^i_\# \left(\Phi^{\frac{T}{3}}_{\theta_1}(\mu_0^i)\right)=\Phi^{\frac{T}{3}}_{\theta_3}(\mu_1^i).
\end{equation}
We consider
\begin{equation*}
    \mu=\sum_{i=1}^N \Phi_{\theta_1}^{\frac{T}{3}}(\mu_0^i),
\end{equation*}
and use \Cref{lem: univ.approx} to find a flow map $\Psi_\varepsilon:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ such that
\begin{equation} \label{eq: second.psi}
    \left\|\Psi^i-\Psi_\varepsilon\Big|_{\mathrm{supp}\left(\Phi_{\theta_1}^{\frac{T}{3}}(\mu_0^i)\right)}\right\|_{L^2\left(\Phi_{\theta_1}^{\frac{T}{3}}(\mu_0^i)\right)}\leqslant\|\Psi-\Psi_\varepsilon\|_{L^2(\mu)}\leqslant\frac{\varepsilon}{C}
\end{equation}
for $i\in[N]$. In fact by virtue of \Cref{lem: univ.approx} there exists a parameterized flow map
\begin{equation*}
    \Phi_{\theta_2}^{t}:\mathscr{P}(\mathbb{S}^{d-1})\to \mathscr{P}(\mathbb{S}^{d-1})
\end{equation*}
for $t\in[T/3,2T/3]$, induced by \eqref{eq: cauchy.pb} and defined, for $\nu\in \mathscr{P}(\mathbb{S}^{d-1})$, as
\begin{equation*}
    \Phi_{\theta_2}^{\frac{2T}{3}}(\nu)=(\Psi_\varepsilon)_\#\nu,
\end{equation*}
which by virtue of \eqref{eq: first.psi}, \eqref{eq: second.psi} and \Cref{lem: monge}, satisfies
\begin{equation}\label{eq: gluing.flow}
    \mathsf{W}_2\left(\left(\Phi_{\theta_2}^{\frac{2T}{3}}\circ \Phi_{\theta_1}^{\frac{T}{3}}\right)(\mu_0^i),\Phi_{\theta_3}^{T}(\mu_1^i)\right)\leqslant\frac{\varepsilon}{C}
\end{equation}
for all $i\in[N]$.

\subsubsection*{Step 3. Continuity}

We now apply the inverse of $\Phi_{\theta_3}^{T}$ to conclude that
the map
\begin{equation*}
\Phi_{\text{fin}}^T:=\left(\Phi_{\theta_3}^{T}\right)^{-1}\circ\Phi_{\theta_2}^{\frac{2T}{3}}\circ \Phi_{\theta_1}^{\frac{T}{3}}
\end{equation*}
satisfies
\begin{align*}
\mathsf{W}_2\left(\Phi_{\text{fin}}^T (\mu_0^i),\mu_1^i\right) &= \mathsf{W}_2\left(\Phi_{\text{fin}}^T (\mu_0^i), \left(\left(\Phi_{\theta_3}^T\right)^{-1}\circ\Phi_{\theta_3}^T\right) (\mu_1^i)\right)\\
    &\overset{\eqref{eq: continuity.inverse.flow}}{\leqslant}  C\cdot\mathsf{W}_2\left(\left(\Phi_{\theta_2}^{\frac{2T}{3}}\circ \Phi_{\theta_1}^{\frac{T}{3}}\right) (\mu_0^i),\Phi_{\theta_3}^T (\mu_1^i)\right)\\
    &\overset{\eqref{eq: gluing.flow}}{\leqslant}\varepsilon,
\end{align*}
for all $i\in[N]$, as desired.

 \label{proof: proof.restricted}
We assume that the target measures $\mu_1^i$ are all empirical measures with $M \geqslant 2$ atoms:
\begin{equation*}
    \mu_1^i = \frac{1}{M}\sum_{m=1}^M \delta_{y_m^i},
\end{equation*}
for some $y_m^i \in \mathbb{S}^{d-1}$. The input measures $\mu_0^i$ are assumed to be absolutely continuous with respect to the normalized Lebesgue measure, in addition to satisfying \eqref{eq: assumption.hole}. Under these assumptions, the following proof
is very similar to that of \Cref{thm: targets.atoms}---it avoids the packing step of \Cref{prop: compression}, and avoids a direct application of \Cref{lem: univ.approx}, steps where the number of switches are hard to track. We split the proof in three steps.

\subsubsection*{Step 1. Disentanglement}
As before, we first disentangle the measures using \Cref{prop: separation}. Furthermore since the vector field in \eqref{eq: cauchy.pb} is Lipschitz, absolute continuity of all measures is preserved over time, and thus we find flow maps
\begin{equation*}
    \Phi_{\theta_1}^{t}:\mathscr{P}_{\mathrm{ac}}(\mathbb{S}^{d-1})\mapsto \mathscr{P}_{\mathrm{ac}}(\mathbb{S}^{d-1})
\end{equation*}
for $t\in[0,T/5]$, and
\begin{equation*}
    \Phi_{\theta_5}^{t}:\mathscr{P}(\mathbb{S}^{d-1})\mapsto\mathscr{P}(\mathbb{S}^{d-1})
\end{equation*}
for $t\in[4T/5, T]$, induced by the characteristics of \eqref{eq: cauchy.pb} and piecewise constant parameters having $O(d\cdot N)$ switches, which satisfy
\begin{equation*}
   \mathrm{conv}_g\,\mathrm{supp}\left(\Phi_{\theta_1}^{\frac{T}{5}}(\mu_0^i)\right)\cap \mathrm{conv}_g\,\mathrm{supp}\left(\Phi_{\theta_1}^{\frac{T}{5}}(\mu_0^j)\right)=\varnothing\hspace{1cm}\text{ if }i\neq j,
\end{equation*}
and 
\begin{equation*}
    \mathrm{conv}_g\,\mathrm{supp}\left(\Phi_{\theta_5}^{T}(\mu_1^i)\right)\cap \mathrm{conv}_g\,\mathrm{supp}\left(\Phi_{\theta_5}^{T}(\mu_1^j)\right)=\varnothing\hspace{1cm}\text{ if }i\neq j.
\end{equation*}
We label the disentangled targets as
\begin{equation} \label{eq: relabelling.target}
    \Phi_{\theta_5}^{T}(\mu_1^i)=\frac{1}{M}\sum_{m=1}^M\delta_{\widetilde{y}_m^i}.
\end{equation}

\subsubsection*{Step 2. Clustering}
Let $\varepsilon_1>0$ be arbitrary and to be chosen later on.
We first employ \Cref{prop: targets.atoms} to cluster the disentangled input measures: there exists a flow map
\begin{equation*}
