        \Lambda^t\big(x,y\big)=\left(\Phi^t(x),\Psi^t(y)\right),
    \end{equation*}
    where $\Phi^t:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ and $\Psi^t:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ are the flow maps induced by \eqref{eq: cauchy.pb.W=0} with data $\mu_0$ and $\nu_0$. Namely, setting $v[\upnu](x) = \bm{\mathsf{P}}^\perp_x \mathscr{A}_{\bm{\mathit{B}}}[\upnu](x)$, $\Phi^t$ solves
    \begin{equation*}
        \begin{dcases}
            \displaystyle\frac{\, \mathrm{d}}{\, \mathrm{d} \tau}\Phi^\tau(x)= v[\mu(\tau)](\Phi^\tau(x)) &\tau\in[0,t]\\
            \Phi^0(x)=x,
        \end{dcases}
    \end{equation*}
    and $\Psi^t$ solves
    \begin{equation*}
        \begin{dcases}
            \frac{\, \mathrm{d}}{\, \mathrm{d} \tau}\Psi^\tau(x)= v[\nu(\tau)](\Psi^\tau(x)) & \tau\in[0,t]\\
            \Psi^0(x)=x.
        \end{dcases}
    \end{equation*}
    We have $\mu(t)=\Phi^t_\#\mu_0$ and $\nu(t)=\Psi^t_\#\nu_0$, and $\Lambda_\#^t\gamma$ is a transport plan between $\mu(t)$ and $\nu(t)$.
    Denote by $\Pi^x:\mathbb{S}^{d-1}\times \mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ (resp. $\Pi^y$) the projection operator onto the first (resp. second) variable. Note that
    \begin{equation*}       \left(\Pi^x\circ\Lambda^t\right)\big(x,y\big)=\Phi^t(x)=\left( \Phi^t\circ \Pi^x \right)\big(x,y\big).
    \end{equation*}
    Therefore
    \begin{equation*}
\Pi^x_\#\left(\Lambda^t_\#\gamma_0\right)=\left(\Pi^x\circ\Lambda^t\right)_\#\gamma_0=\left(\Phi^t\circ \Pi^x\right)_\#\gamma_0=\Phi^t_\#\mu_0.
    \end{equation*}
    (Analogous computations follow for $\Pi^y_\#(\Lambda^t_\#\gamma_0)$.)
    Therefore,
    \begin{align*}
        \mathsf{W}_p(\mu(t),\nu(t))&\leqslant \left(\iint d_g(x,y)^p\Lambda^t_\#\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}\\
        &=\left(\iint d_g(\Phi^t(x),\Psi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}.
    \end{align*}
    We thus have 
    \begin{align}
        \mathsf{W}_p(\mu(t),\nu(t))&\leqslant \left(\iint d_g(\Phi^t(x),\Phi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}\nonumber\\
        &+\left(\iint d_g(\Phi^t(y),\Psi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}.\label{eq: gronwall.two.integrals}
    \end{align}
    We analyze the integrals above separately, starting with the first one, since $v[\mu](\cdot)$ is Lipschitz, by the Grönwall Lemma, the flow map $\Phi^t$ is Lipschitz as well:
    \begin{align}
       \iint d_g(\Phi^t(x),\Phi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)&\leqslant K_1^pe^{pK_0 t} \iint d_g(x,y)^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\label{eq: gronwall.fisrt}
    \end{align}
    where $K_1\geqslant 1$ and $K_0>0$ depend only on $\bm{\mathit{B}}$.  
    For the second integral, setting $f(t, y)=\|\Phi^t(y)-\Psi^t(y)\|$, since both flows are actually $\mathscr{C}^\infty$ on $\mathbb{R}_{\geqslant0}\times\mathbb{S}^{d-1}$,  for a.e. $t$ and $y$ we can differentiate to find
    \begin{align*}
        \partial_t f(t, y)&\leqslant \bigg\|v[\mu(t)](\Phi^t(y))-v[\nu(t)](\Psi^t(y))\bigg\|\\
        &\leqslant \bigg\|v[\mu(t)](\Phi^t(y))-v[\nu(t)](\Phi^t(y))\bigg\|+ \bigg\|v[\nu(t)](\Phi^t(y))-v[\nu(t)](\Psi^t(y))\bigg\|\\
        &\leqslant \big\|v[\mu(t)]-v[\nu(t)]\big\|_{L^\infty(\mathbb{S}^{d-1})}+C_0 d_g(\Phi^t(y),\Psi^t(y))\\
        &\leqslant C_1\mathsf{W}_p(\mu(t),\nu(t))+C_0 f(t, y),
    \end{align*}
    where $C_1, C_0\geqslant 0$ depend only on $\bm{\mathit{B}}$ as shown in \cite{geshkovski2024emergence, castin2023understanding}.
    Applying Grönwall's inequality, and noting that $f(0, \cdot)\equiv0$, we obtain
    \begin{equation*}
        f(t, y)\leqslant \int_0^te^{C_1(t-s)}\mathsf{W}_p(\mu(s),\nu(s))\, \mathrm{d} s.
    \end{equation*}
    Therefore, 
\begin{equation}\label{eq: gronwall.second}
    \iint d_g(\Phi^t(y),\Psi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\leqslant C_2^p  \left(\int_0^t e^{C_1(t-s)}\mathsf{W}_p(\mu(s),\nu(s))\, \mathrm{d} s\right)^p.
\end{equation}
where $C_2>0$ is such $d_g(z_1,z_2)\leqslant C_2\|z_1-z_2\|$ for all $z_1,z_2\in \mathbb{S}^{d-1}$, and thus, independent of $p$.
Gathering \eqref{eq: gronwall.fisrt} and \eqref{eq: gronwall.second} in \eqref{eq: gronwall.two.integrals}, we find
\begin{align*}
    \mathsf{W}_p(\mu(t),\nu(t))\leqslant K_1e^{K_0t}\mathsf{W}_p(\mu_0,\nu_0)+C_2\int_0^t e^{C_1 (t-s)}\mathsf{W}_p(\mu(s),\nu(s))\, \mathrm{d} s.
\end{align*}
Employing the integral form of Grönwall's inequality, we end up with
\begin{equation*}
    \mathsf{W}_p(\mu(t),\nu(t))\leqslant M_0 e^{e^{M_1t}}\mathsf{W}_p(\mu_0,\nu_0)
\end{equation*}
for $M_0\geqslant 1$ and $M_1>0$ depending only on $\bm{\mathit{B}}$.
Since none of the constants depend on $p$, we can let $p\to +\infty$ to conclude.

\begin{align*}
        \mathsf{W}_p(\mu(t),\nu(t))&\leqslant \left(\iint d_g(x,y)^p\Lambda^t_\#\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}\\
        &=\left(\iint d_g(\Phi^t(x),\Psi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}.
    \end{align*}

\begin{align}
        \mathsf{W}_p(\mu(t),\nu(t))&\leqslant \left(\iint d_g(\Phi^t(x),\Phi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}\nonumber\\
        &+\left(\iint d_g(\Phi^t(y),\Psi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\right)^{\frac{1}{p}}.\label{eq: gronwall.two.integrals}
    \end{align}

\begin{align}
       \iint d_g(\Phi^t(x),\Phi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)&\leqslant K_1^pe^{pK_0 t} \iint d_g(x,y)^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\label{eq: gronwall.fisrt}
    \end{align}

\begin{equation}\label{eq: gronwall.second}
    \iint d_g(\Phi^t(y),\Psi^t(y))^p\gamma_0(\, \mathrm{d} x,\, \mathrm{d} y)\leqslant C_2^p  \left(\int_0^t e^{C_1(t-s)}\mathsf{W}_p(\mu(s),\nu(s))\, \mathrm{d} s\right)^p.
\end{equation}

Note that $\|\mathbb{E}_{\mu(t)}[x]\|>0$ since $\mathrm{supp}(\mu_0)$ is contained in a hemisphere.
Set 
$$
\gamma(t):=\frac{\mathbb{E}_{\mu(t)}[x]}{\|\mathbb{E}_{\mu(t)}[x]\|}.
$$ 
and consider
\begin{equation*} 
    \mathsf{V}[\mu(t)](t):=\int\|x-\gamma(t)\|^2\mu(t,\, \mathrm{d} x).
\end{equation*}
We first show that $\mathsf{V}[\mu(t)](t)$ decays exponentially fast.
Integration by parts yields
 \begin{align}
     \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&=2\|\mathbb{E}_{\mu(t)}[x]\|\left(-1+\int \langle x, \gamma(t)\rangle^2\mu(t,\, \mathrm{d} x)\right)\nonumber\\
     &\hspace{1cm}+2\int \langle x-\gamma(t),-\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} x).\label{eq: differentiation.lyapunov}
 \end{align}
 Owing to \Cref{prop: targets.atoms}, for any $\varepsilon_0>0$ there is some $t_0>0$ such that for all $t\geqslant t_0$, we have 
 \begin{equation}\label{eq: smallness}
     d_g(x,y)\leqslant \varepsilon_0 \hspace{1cm} \text{ for all }x,y\in \mathrm{supp}(\mu(t_0)).
 \end{equation} 
 We treat the terms in \eqref{eq: differentiation.lyapunov} separately, starting with
 \begin{align}
     -1+\int \langle x, \gamma(t)\rangle^2\mu(t,\, \mathrm{d} x)&=-1+\int \cos^2\left(d_g(x,\gamma)\right)\mu(t,\, \mathrm{d} x)\nonumber\\
     &=-1+\int\left(1-\frac{1}{2}d_g(x,\gamma)^2+O\left(\varepsilon_0^4\right)\right)^2\mu(t,\, \mathrm{d} x)\nonumber\\
     &=-\int d_g(x,\gamma)^2\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right).
     \label{eq: expectation.term}
 \end{align}
On the other hand,
 \begin{align}
     \dot{\gamma}(t)&=\int \bm{\mathsf{P}}^\perp_x(\gamma(t)) \mu(t,\, \mathrm{d} x)-\frac{\mathbb{E}_{\mu(t)}[x]}{\|\mathbb{E}_{\mu(t)}[x]\|^2}\left\langle \frac{\mathbb{E}_{\mu(t)}[x]}{\|\mathbb{E}_{\mu(t)}[x]\|},\int y\partial_t\mu(t,\, \mathrm{d} y)\right\rangle\nonumber\\
     &=\int \bm{\mathsf{P}}^\perp_x(\gamma(t)) \mu(t,\, \mathrm{d} x)-\gamma(t)\left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right).
     \label{eq: gamma.prime}
 \end{align}
 Plugging \eqref{eq: gamma.prime} into the second term in \eqref{eq: differentiation.lyapunov}, we find
 \begin{align}
     \int \langle y-\gamma(t),\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y)&=\int \langle y,\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y)-\frac{1}{2}\int \frac{\, \mathrm{d}}{\, \mathrm{d} t}\langle \gamma(t),\gamma(t)\rangle \mu(t,\, \mathrm{d} y) \nonumber\\
     &=\int \langle y,\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y).\label{eq: to.develop}  \end{align}
Expanding the inner product in \eqref{eq: to.develop}, we obtain
\begin{align}
    \langle y,\dot{\gamma}(t)\rangle&=\int\left\langle y,\bm{\mathsf{P}}^\perp_x\gamma(t)\right\rangle\mu(t,\, \mathrm{d} x)-\left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right) \langle y,\gamma(t)\rangle\nonumber\\
    &=\int\left(\langle y,\gamma(t)\rangle -\langle \gamma(t),x\rangle \langle x,y\rangle\right) \mu(t,\, \mathrm{d} x)
    \nonumber\\
    &\hspace{4cm}-\left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right) \langle y,\gamma(t)\rangle\nonumber\\
    &=-\int \langle \gamma(t),x\rangle \langle x,y\rangle \mu(t,\, \mathrm{d} x)+\left(\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right) \langle y,\gamma(t)\rangle\nonumber\\
    &=-\int  \cos(d_g(\gamma(t),x)) \cos(d_g(x,y)) \mu(t,\, \mathrm{d} x)\nonumber\\
    &\hspace{1.5cm}+\left(\int \cos^2(d_g(\gamma(t),x))\mu(t,\, \mathrm{d} x)\right) \cos(d_g(y,\gamma(t))).\label{eq: several.cosines}
\end{align}
In view of \eqref{eq: smallness}, we Taylor expand to find
\begin{align}
    &\int  \cos(d_g(\gamma(t),x) )\cos(d_g(x,y)) \mu(t,\, \mathrm{d} x)\nonumber\\
    &=\int \left(1-\frac{d_g(\gamma(t),x)^2}{2}+O\left(\varepsilon_0^4\right)\right)\left(1-\frac{d_g(y,x)^2}{2}+O\left(\varepsilon_0^4\right)\right)\mu(t,\, \mathrm{d} x)\nonumber\\
    &=\int \left(1-\frac{d_g(\gamma(t),x)^2}{2}-\frac{d_g(y,x)^2}{2}\right)\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right),\label{eq: first.first.term}
\end{align}
and
\begin{align}
    &\left(\int \cos^2(d_g(\gamma(t),x))\mu(t,\, \mathrm{d} x)\right) \cos(d_g(y,\gamma(t)))\nonumber\\
    &=\left(\int \left(1-d_g(\gamma(t),x)^2+O\left(\varepsilon_0^4\right)\right)\mu(t,\, \mathrm{d} x)\right) \left(1-\frac{d_g(y,\gamma(t))^2}{2}+O\left(\varepsilon_0^4\right)\right)\nonumber\\
    &=\left(\int (1-d_g(\gamma(t),x)^2)\mu(t,\, \mathrm{d} x)\right)-\frac{d_g(y,\gamma(t))^2}{2}+O\left(\varepsilon_0^4\right).\label{eq: first.second.term}
\end{align}
Combining \eqref{eq: first.first.term} and \eqref{eq: first.second.term} in \eqref{eq: several.cosines} we obtain
\begin{align*}
    \langle y,\dot{\gamma}(t)\rangle &=\left(\int (1-d_g(\gamma(t),x)^2)\mu(t,\, \mathrm{d} x)\right)-\frac{d_g(y,\gamma(t))^2}{2}\nonumber\\
    &\hspace{0.5cm}-\int \left(1-\frac{d_g(\gamma(t),x)^2}{2}-\frac{d_g(y,x)^2}{2}\right)\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right)\nonumber\\
    &=-\int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)-\frac{d_g(y,\gamma(t))^2}{2}\nonumber\\
    &\hspace{0.5cm}+\frac{1}{2}\int \left(d_g(\gamma(t),x)^2+d_g(y,x)^2\right)\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right).
\end{align*}
Going back to \eqref{eq: to.develop}, using \eqref{eq: expectation.term} we gather that
\begin{align}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&=2\|\mathbb{E}_{\mu(t)}[x]\|\left(-\int d_g(x,\gamma(t))^2\mu(t,\, \mathrm{d} x)\right)-2\int \langle y,\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y)\nonumber\\
    &=-2\int d_g(x,\gamma(t))^2\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^3\right)\nonumber\\
    &\hspace{1cm} - \int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)-\iint d_g(y,x)^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)\nonumber\\
    &\hspace{1cm} +2\int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)+\int d_g(y,\gamma(t))^2\mu(t,\, \mathrm{d} y),\label{eq: putting.together}
\end{align}
where we used \eqref{eq: smallness} to ensure $\|\mathbb{E}_{\mu(t)}[x]\|=1-O(\varepsilon_0)$. 
Combining terms in \eqref{eq: putting.together},
\begin{align*}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&=\int d_g(y,\gamma(t))^2\mu(t,\, \mathrm{d} y)+O\left(\varepsilon_0^3\right)\nonumber\\
    &-\int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)-\iint d_g(y,x)^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)\nonumber\\
    &=-\iint d_g(y,x)^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)+O\left(\varepsilon_0^3\right).
\end{align*}
Taking $\varepsilon_0$ small enough, 
\begin{equation} \label{eq: diff.ineq.first}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)\leqslant - c\iint \|y-x\|^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)
\end{equation}
for some $c>0$ and all $t\geqslant t_0$. Fixing $t$, we consider the change of variables
\begin{equation*}
    y=\gamma(t)+z,\hspace{1cm}\mathsf{T}(y)=y-\gamma(t),
\end{equation*}
and \eqref{eq: diff.ineq.first} rewrites as
\begin{equation}\label{eq: diff.ineq.first.reload}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)\leqslant - c\iint \|\gamma(t)+z-x\|^2\mu(t,\, \mathrm{d} x)\nu(t,\, \mathrm{d} z)
\end{equation}
where $\nu(t)=\mathsf{T}_\#\mu(t).$
Expanding in \eqref{eq: diff.ineq.first.reload} we find
\begin{align} \label{eq: diff.ineq.second}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&\leqslant - c\iint \left(\|\gamma(t)-x\|^2+\|z\|^2+2\langle z,\gamma(t)-x\rangle\right)\mu(t,\, \mathrm{d} x)\nu(t,\, \mathrm{d} z)\nonumber\\
    &=- c\int\|\gamma(t)-x\|^2\mu(t,\, \mathrm{d} x)-c\int \|z\|^2\nu(\, \mathrm{d} z)\nonumber\\
    &\hspace{4cm}-2c\iint \langle z,\gamma(t)-x\rangle\mu(t,\, \mathrm{d} x)\nu(t,\, \mathrm{d} z)\nonumber\\
    &\leqslant -c\mathsf{V}[\mu(t)](t)+O\left(\varepsilon_0^3\right)\nonumber\\
    &\leqslant -c_0\mathsf{V}[\mu(t)](t)
\end{align}
for some $c_0>0$ and all $t\geqslant t_0$, by choosing $\varepsilon_0$ small enough. By virtue of Gr\"onwall's lemma,
\begin{equation}\label{eq: exp.decay}
    \mathsf{V}[\mu(t)](t)\leqslant c_1e^{-c_0t}
\end{equation}
for some constant $c_1\geqslant 1$ and for all $t\geqslant t_0$. We now use \eqref{eq: exp.decay} to conclude. We make use of  
\begin{align} \mathsf{W}_2^2\left(\mu(t),\updelta_{\gamma(t)}\right)&\lesssim\int \left\|x-\gamma(t)\right\|^2\mu(t,\, \mathrm{d} x)\label{eq: W2.transport}\\
&=\int_{\{\|x-\gamma(t)\|^2\leqslant\alpha\}} \left\|x-\gamma(t)\right\|^2\mu(t,\, \mathrm{d} x)\nonumber\\
&\hspace{1cm}+\int_{\{\|x-\gamma(t)\|^2>\alpha\}} \left\|x-\gamma(t)\right\|^2\mu(t,\, \mathrm{d} x) \nonumber,
\end{align}
for $\alpha>0$ to be determined later on, where we recall the integrals are taken over $\mathbb{S}^{d-1}$, and the first inequality follows by equivalence of norms and by considering the (optimal) transport plan which corresponds to $\mathsf{T}(x)=\gamma(t)$.
We only need to estimate the second term in \eqref{eq: W2.transport}. 
By Markov's inequality and \eqref{eq: exp.decay}, we find
\begin{equation*}
    \mu\left(t,\left\{x\in \mathbb{S}^{d-1}:\, \|x-\gamma(t)\|^2>\alpha\right\}\right)\leqslant \frac{\mathsf{V}[\mu(t)](t)}{\alpha}\leqslant \frac{c_1e^{-2c_0 t}}{\alpha}.
\end{equation*}
Picking $\alpha=c_1e^{-c_0t}$, we deduce
\begin{equation*}
   \mu\left(t,\left\{x\in \mathbb{S}^{d-1}:\, \|x-\gamma(t)\|^2> c_1e^{-c_0t}\right\}\right)\leqslant e^{-c_0t}.
\end{equation*}
Coming back to \eqref{eq: W2.transport}, we find
\begin{equation*} 
   \mathsf{W}_2^2\left(\mu(t),\updelta_{\gamma(t)}\right)
   \lesssim e^{-c_0 t} +  2\pi\cdot\mu\left(t,\{\|x-\gamma(t)\|^2>\alpha\}\right)\lesssim e^{-c_0 t}
\end{equation*}
for all $t\geqslant 0$.
To conclude the proof, it suffices to show that
\begin{equation*}
    d_g(x_0,\gamma(t))\lesssim e^{-c_2 t}
\end{equation*}
for some constant $c_2>0$ and for all $t\geqslant 0$.
Similar computations to \eqref{eq: several.cosines} give
\begin{align*}
    \dot{\gamma}(t)&=\int \bm{\mathsf{P}}^\perp_x(\gamma(t))\mu(t,\, \mathrm{d} x)-\gamma(t) \left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right)\\
    &=-\int \cos(d_g(x,\gamma(t)))x\mu(t,\, \mathrm{d} x)+\gamma(t)\int \cos^2(d_g(x,\gamma(t))\mu(t,\, \mathrm{d} x)\\
    &=-\int \cos(d_g(x,\gamma(t)))x\mu(t,\, \mathrm{d} x)+\gamma(t)\int \cos^2(d_g(x,\gamma(t))\mu(t,\, \mathrm{d} x).
\end{align*}
We Taylor expand in the above identity to find
\begin{align*}
    \dot{\gamma}(t)&=-\int\left(1-\frac{d_g(x,\gamma(t))^2}{2}\right)x\mu(t,\, \mathrm{d} x)\nonumber\\
    &\hspace{3cm}+\gamma(t)\int (1-d_g(x,\gamma(t))^2)\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right)\nonumber\\
    &=-\int\left(1-\frac{d_g(x,\gamma(t))^2}{2}\right)(x-\gamma(t)+\gamma(t))\mu(t,\, \mathrm{d} x)\nonumber\\
    &\hspace{3cm}+\gamma(t)\int (1-d_g(x,\gamma(t))^2)\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right)\nonumber\\
    &=-\int\left(1-\frac{d_g(x,\gamma(t))^2}{2}\right)(x-\gamma(t))\mu(t,\, \mathrm{d} x)\nonumber\\
    &\hspace{4cm}-\frac{\gamma(t)}{2}\int d_g(x,\gamma(t))^2\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right).
\end{align*}
By Cauchy-Schwarz and \eqref{eq: exp.decay}, we deduce
\begin{align}
    &\left|\int\left(1-\frac{d_g(x,\gamma(t))^2}{2}\right)(x-\gamma(t))\mu(t,\, \mathrm{d} x)\right|\nonumber\\
    &\hspace{1cm}\leqslant \left(\int\left(1-\frac{d_g(x,\gamma(t))^2}{2}\right)^2\mu(t,\, \mathrm{d} x)\right)^{\frac{1}{2}}\left(\int\|x-\gamma(t)\|^2\mu(t,\, \mathrm{d} x)\right)^{\frac{1}{2}}\nonumber\\
    &\hspace{1cm}\leqslant\sqrt{\mathsf{V}[\mu(t)](t)}\lesssim e^{-\frac{c_0}{2}t}.\label{eq: gam.dot.one}
\end{align}
Similarly,
\begin{equation}\label{eq: gam.dot.two}
    \left|\gamma(t)\int d_g(x,\gamma(t))^2\mu(t,\, \mathrm{d} x)\right|\lesssim \int \|x-\gamma(t)\|^2\mu(t,\, \mathrm{d} x)\lesssim e^{-c_0t}.
\end{equation}
Combining \eqref{eq: gam.dot.one} and \eqref{eq: gam.dot.two}, we deduce
\begin{equation*}
    \lim_{t\to +\infty}\gamma(t)=x_0\hspace{1cm}\text{and}\hspace{1cm} |\dot{\gamma}(t)|\lesssim e^{-\frac{c_0}{2} t}
\end{equation*}
for all $t\geqslant t_0$. We conclude the proof by observing that 
\begin{align*}
    1-\langle x_0, \gamma(t)\rangle &=\langle x_0,\gamma(+\infty)\rangle-\langle x_0,\gamma(t)\rangle\\
    &=\int_t^{+\infty}\frac{\, \mathrm{d}}{\, \mathrm{d} s} \langle x_0,\gamma(s)\rangle \, \mathrm{d} s\lesssim e^{-\frac{c_0}{2}t}. \qedhere
\end{align*}

\begin{align}
     \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&=2\|\mathbb{E}_{\mu(t)}[x]\|\left(-1+\int \langle x, \gamma(t)\rangle^2\mu(t,\, \mathrm{d} x)\right)\nonumber\\
     &\hspace{1cm}+2\int \langle x-\gamma(t),-\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} x).\label{eq: differentiation.lyapunov}
 \end{align}

\begin{align}
     -1+\int \langle x, \gamma(t)\rangle^2\mu(t,\, \mathrm{d} x)&=-1+\int \cos^2\left(d_g(x,\gamma)\right)\mu(t,\, \mathrm{d} x)\nonumber\\
     &=-1+\int\left(1-\frac{1}{2}d_g(x,\gamma)^2+O\left(\varepsilon_0^4\right)\right)^2\mu(t,\, \mathrm{d} x)\nonumber\\
     &=-\int d_g(x,\gamma)^2\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^4\right).
     \label{eq: expectation.term}
 \end{align}

\begin{align}
     \int \langle y-\gamma(t),\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y)&=\int \langle y,\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y)-\frac{1}{2}\int \frac{\, \mathrm{d}}{\, \mathrm{d} t}\langle \gamma(t),\gamma(t)\rangle \mu(t,\, \mathrm{d} y) \nonumber\\
     &=\int \langle y,\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y).\label{eq: to.develop}  \end{align}

\begin{align}
    \langle y,\dot{\gamma}(t)\rangle&=\int\left\langle y,\bm{\mathsf{P}}^\perp_x\gamma(t)\right\rangle\mu(t,\, \mathrm{d} x)-\left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right) \langle y,\gamma(t)\rangle\nonumber\\
    &=\int\left(\langle y,\gamma(t)\rangle -\langle \gamma(t),x\rangle \langle x,y\rangle\right) \mu(t,\, \mathrm{d} x)
    \nonumber\\
    &\hspace{4cm}-\left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right) \langle y,\gamma(t)\rangle\nonumber\\
    &=-\int \langle \gamma(t),x\rangle \langle x,y\rangle \mu(t,\, \mathrm{d} x)+\left(\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right) \langle y,\gamma(t)\rangle\nonumber\\
    &=-\int  \cos(d_g(\gamma(t),x)) \cos(d_g(x,y)) \mu(t,\, \mathrm{d} x)\nonumber\\
    &\hspace{1.5cm}+\left(\int \cos^2(d_g(\gamma(t),x))\mu(t,\, \mathrm{d} x)\right) \cos(d_g(y,\gamma(t))).\label{eq: several.cosines}
\end{align}

\begin{align}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&=2\|\mathbb{E}_{\mu(t)}[x]\|\left(-\int d_g(x,\gamma(t))^2\mu(t,\, \mathrm{d} x)\right)-2\int \langle y,\dot{\gamma}(t)\rangle \mu(t,\, \mathrm{d} y)\nonumber\\
    &=-2\int d_g(x,\gamma(t))^2\mu(t,\, \mathrm{d} x)+O\left(\varepsilon_0^3\right)\nonumber\\
    &\hspace{1cm} - \int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)-\iint d_g(y,x)^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)\nonumber\\
    &\hspace{1cm} +2\int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)+\int d_g(y,\gamma(t))^2\mu(t,\, \mathrm{d} y),\label{eq: putting.together}
\end{align}

\begin{align*}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t} \mathsf{V}[\mu(t)](t)&=\int d_g(y,\gamma(t))^2\mu(t,\, \mathrm{d} y)+O\left(\varepsilon_0^3\right)\nonumber\\
    &-\int d_g(\gamma(t),x)^2\mu(t,\, \mathrm{d} x)-\iint d_g(y,x)^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)\nonumber\\
    &=-\iint d_g(y,x)^2\mu(t,\, \mathrm{d} x)\mu(t,\, \mathrm{d} y)+O\left(\varepsilon_0^3\right).
\end{align*}

\begin{align*}
    \dot{\gamma}(t)&=\int \bm{\mathsf{P}}^\perp_x(\gamma(t))\mu(t,\, \mathrm{d} x)-\gamma(t) \left(1-\int \langle \gamma(t),x\rangle^2\mu(t,\, \mathrm{d} x)\right)\\
    &=-\int \cos(d_g(x,\gamma(t)))x\mu(t,\, \mathrm{d} x)+\gamma(t)\int \cos^2(d_g(x,\gamma(t))\mu(t,\, \mathrm{d} x)\\
    &=-\int \cos(d_g(x,\gamma(t)))x\mu(t,\, \mathrm{d} x)+\gamma(t)\int \cos^2(d_g(x,\gamma(t))\mu(t,\, \mathrm{d} x).
\end{align*}

\begin{align*}
    1-\langle x_0, \gamma(t)\rangle &=\langle x_0,\gamma(+\infty)\rangle-\langle x_0,\gamma(t)\rangle\\
    &=\int_t^{+\infty}\frac{\, \mathrm{d}}{\, \mathrm{d} s} \langle x_0,\gamma(s)\rangle \, \mathrm{d} s\lesssim e^{-\frac{c_0}{2}t}. \qedhere
\end{align*}

 \label{lem: tubular.mass.movement}
Consider $K+1$ open balls $\mathscr{B}_K,\ldots,\mathscr{B}_1,\mathscr{B}_0\subset \mathbb{S}^{d-1}$ satisfying
\begin{align*}
        \mathscr{B}_k\cap\mathscr{B}_{k-1}\neq\varnothing \hspace{1cm} &\text{ for } k\in[K]\\
        \mathscr{B}_k\cap\mathscr{B}_{k'}=\varnothing \hspace{1cm} &\text{ if }|k-k'|\geqslant 2.
\end{align*}
Then for any $T>0$ and $\varepsilon>0$, there exist $(\bm{\mathit{W}},\bm{\mathit{V}},b):[0,T]\to\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d$,  piecewise constant having at most $K$ switches, such that for any $\mu_0\in \mathscr{P}(\mathbb{S}^{d-1})$, the corresponding unique solution $\mu\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to 
\begin{equation} \label{eq: neural.pde.sphere}
\begin{cases}
\partial_t\mu(t)+\mathrm{div}\left(\bm{\mathsf{P}}^\perp_x\left(\bm{\mathit{W}}(t)\Big(\bm{\mathit{U}}(t) x+b(t)\Big)_+\right)\mu(t)\right)=0 &\text{ on } [0, T]\times\mathbb{S}^{d-1}\\
\mu(0)=\mu_0 &\text{ on } \mathbb{S}^{d-1}
\end{cases}
\end{equation}
satisfies
    \begin{equation*}
        \mu(T,\mathscr{B}_K)\geqslant (1-\varepsilon)^K\mu_0\left(\mathscr{B}_0\right).
    \end{equation*}
    Moreover, $\mu(T)=\Phi^T_\#\mu_0$ for a Lipschitz-continuous, invertible map $\Phi^t:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ which satisfies
    \begin{equation}\label{eq: eq.tubular.mass.movement}
        \Phi^t(x)=x\hspace{1cm}\text{ for }x\notin \bigcup_{k=0}^K \mathscr{B}_k
    \end{equation}
    for all $t\in[0,T]$.

\label{lem: two.balls}
   Consider two open balls $\mathscr{B}_0,\mathscr{B}_1\subset \mathbb{S}^{d-1}$ such that $\mathscr{B}_0\cap\mathscr{B}_1\neq\varnothing$.
   For any $\varepsilon>0$ and $T>0$, there exist $\bm{\mathit{W}},\bm{\mathit{U}}\in\mathscr{M}_{d\times d}(\mathbb{R})$ and $b\in\mathbb{R}^d$ such that for any $\mu_0\in\mathscr{P}(\mathbb{S}^{d-1})$, the unique solution $\mu\in \mathscr{C}^0([0, T];\mathscr{P}(\mathbb{S}^{d-1}))$ to \eqref{eq: neural.pde.sphere} satisfies
   \begin{equation} \label{eq: claim.statement.lemmaA1}
       \mu(T, \mathscr{B}_0\cap\mathscr{B}_1)\geqslant(1-\varepsilon)\mu_0(\mathscr{B}_0).
   \end{equation}
   Moreover $\mu(T)=\Phi^T_\#\mu_0$ where the Lipschitz-continuous and invertible flow map $\Phi^t:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ of \eqref{eq: neural.ode.sphere} satisfies 
   \begin{equation*}
   (\Phi^t)_{\mid\mathbb{S}^{d-1}\setminus \mathscr{B}_0}\equiv\mathrm{Id} \hspace{1cm} \text{ for } t\in[0,T].    
   \end{equation*}
   Furthermore, for an arbitrary $\omega\in \mathrm{int}(\mathscr{B}_0)$, we can also choose $\bm{\mathit{W}},\bm{\mathit{V}}$ and $b$, so that the solution to \eqref{eq: neural.pde.sphere} satisfies:
   \begin{equation*}
       \mathsf{W}_2(\mu(T),\alpha)\leqslant \varepsilon
   \end{equation*}
   where
   \begin{equation*}
       \alpha(A)=\mu_0(\mathscr{B}_0)\updelta_{\omega}(A)+\mu_0(A\setminus\mathscr{B}_0),
   \end{equation*}
   for any Borel set $A\subset \mathbb{S}^{d-1}$.

As done in previous proofs, we can take all time horizons to be as large as desired throughout by rescaling the norm of the parameters.
Let $z\in\mathbb{S}^{d-1}$ denote the center and $R>0$ the radius of $\mathscr{B}_0$. Take an arbitrary $\omega\in\mathrm{int}(\mathscr{B}_0\cap\mathscr{B}_1)$. We consider
\begin{align*}
\bm{\mathit{U}}&=-{\bf1} z^\top,\\
b&=\cos(R){\bf1},
\end{align*}
as well as any $\bm{\mathit{W}}\in \mathscr{M}_{d\times d}(\mathbb{R})$ such that
\begin{equation*}
\bm{\mathit{W}}{\bf1}=\omega.
\end{equation*}
Then
\begin{equation*}
    \bm{\mathit{W}}\left(\bm{\mathit{U}} x+b\right)_+=\Big(-\cos d_g(z,x)+\cos(R)\Big)_+\omega,
\end{equation*}
and note that
\begin{equation}\label{eq: activation.ball}
    \Big(-\cos d_g(z,x)+\cos(R)\Big)_+> 0\hspace{1cm}\iff \hspace{1cm} x\in\mathscr{B}_0.
\end{equation}
Now observe that
\begin{equation}\label{eq: dissipation.sphere}
    \frac{\, \mathrm{d} }{\, \mathrm{d} t}\langle x(t),\omega\rangle=\Big(-\cos d_g(z,x(t)) +\cos(R)\Big)_+\Big(1-\langle x(t),\omega\rangle^2\Big),
\end{equation}
which is positive whenever $x(t)\in\mathscr{B}_0\setminus\{\omega\}$. We claim that this implies the existence of a time $T_\varepsilon>0$ for which
\begin{equation} \label{eq: claim.lemmaA1} 
    \mu(T_\varepsilon,\mathscr{B}_0\cap\mathscr{B}_1)\geqslant(1-\varepsilon)\mu_0(\mathscr{B}_0).
\end{equation}
To prove this claim, let $\delta>0$ be fixed and to be determined later on. 
Because of \eqref{eq: dissipation.sphere}, there exists some $T_\delta>0$ such that
\begin{equation}\label{eq: claim.lemmaA11}
    \Phi^{T_\delta}(x)\in\mathscr{B}_0\cap\mathscr{B}_1\hspace{1cm}\text{ for }x\in B(z,R-\delta),
\end{equation}
where $\Phi^{T_\delta}:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ is the flow map of \eqref{eq: neural.ode.sphere}. Since $\mu(T_\delta)=\Phi^{T_\delta}_\#\mu_0$, we have
\begin{equation} \label{eq: mass.concentration}
    \mu(T_\delta, \mathscr{B}_0\cap\mathscr{B}_1)=\mu_0\Big((\Phi^{T_\delta})^{-1}(\mathscr{B}_0\cap\mathscr{B}_1)\Big)\overset{\eqref{eq: claim.lemmaA11}}{\geqslant}\mu_0(B(z,R-\delta)).
\end{equation}
Taking $\delta>0$ small enough so that $\mu_0(B(z,R-\delta))\geqslant (1-\varepsilon) \mu_0(\mathscr{B}_0)$ yields claim \eqref{eq: claim.lemmaA1}. We conclude that \eqref{eq: claim.statement.lemmaA1} holds by rescaling time. Finally, by virtue of \eqref{eq: activation.ball}, the flow map $\Phi^t$ is such that $\Phi^t(x)=x$ for
$x\in\mathbb{S}^{d-1}\setminus\mathscr{B}_0$ and $t\in[0,T]$.


As for the second part of the statement, take $\mathscr{B}_1=B(\omega,\eta)\subset\mathscr{B}_0$ with $\eta>0$ to be determined later on.
Owing to \eqref{eq: mass.concentration}, we can argue in the same fashion as in the proof of \Cref{prop: compression}. We have
\begin{align*}
\mathsf{W}_1(\mu(T_\delta),\alpha) &= \sup_{\mathrm{Lip}(\phi)\leqslant 1}\left|\int\phi(\mu(T_\delta)-\alpha)\right|\\
    &\hspace{0.2cm}= \sup_{\mathrm{Lip}(\phi)\leqslant 1}\left|\int_{\mathscr{B}_0}\phi(\mu(T_\delta)- \alpha)+\int_{\mathbb{S}^{d-1}\setminus \mathscr{B}_0}\phi(\mu(T_\delta)-\alpha)\right|.
\end{align*}
Let $\overline{\varepsilon}>0$ be arbitrary and to be chosen small enough later.
Using \eqref{eq: mass.concentration}---with $\overline{\varepsilon}$ instead of $\varepsilon$---and the definition of $\mathscr{B}_1$, we find  
\begin{align*}
    \left|\int_{\mathscr{B}_0\setminus\mathscr{B}_1} \phi \left(\mu(T_\delta) -\alpha\right)+ \int_{\mathscr{B}_1} \phi \left(\mu(T_\delta) -\alpha\right)\right|&\leqslant \left|\int_{\mathscr{B}_0\setminus\mathscr{B}_1} \phi \left(\mu(T_\delta) -\alpha\right)\right|\\
      &\hspace{-6cm}+ \left|\int_{\mathscr{B}_1} \phi \mu(T_\delta) -  \mu(T_\delta,\mathscr{B}_1)\phi(\omega)-(\mu_0(\mathscr{B}_0)-\mu(T_\delta,\mathscr{B}_1))\phi(\omega)\right|\\ &\hspace{-6cm}\leqslant\|\nabla\phi\|_{L^\infty(\mathbb{S}^{d-1})}\cdot\eta\cdot\overline{\varepsilon}\cdot\mu_0(\mathscr{B}_0)+\eta+\overline{\varepsilon}\cdot\mu_0(\mathscr{B}_0),
\end{align*}
which tends to $0$ as $\overline{\varepsilon}$ and $\eta$ tend to zero.
On the other hand,
\begin{align*}
    \left|\int_{\mathbb{S}^{d-1}\setminus\mathscr{B}_0}\phi(\mu(T_\delta)-\alpha)\right|=0
\end{align*}
by construction.
We choose $\overline{\varepsilon}$ and $\eta$ small enough in a way that
\begin{equation*}
    \mathsf{W}_1(\mu(T_\delta),\alpha)\leqslant \varepsilon.\qedhere
\end{equation*}

We write 
\begin{equation*}
[0,T)=\bigcup_{k\in[M]} [t_{k-1},t_k)
\end{equation*}
where $t_k=\frac{kT}{K}$, and proceed by backward induction:
\begin{align*}
    \mu(T,\mathscr{B}_K)&=\mu(T,\mathscr{B}_K\setminus\mathscr{B}_{K-1})+\mu(T,\mathscr{B}_K\cap \mathscr{B}_{K-1})\\
&\geqslant \mu(t_{K-1},\mathscr{B}_K\setminus\mathscr{B}_{K-1})+(1-\varepsilon)\mu(t_{K-1},\mathscr{B}_{K-1}),
\end{align*}
where the last inequality follows from \Cref{lem: two.balls}. Using $\mathscr{B}_k\cap\mathscr{B}_{k'}=\varnothing$ whenever $|k-k'|\geqslant 2$, we arrive to
\begin{equation*}
    \mu(T,\mathscr{B}_k)\geqslant \sum_{k=1}^K (1-\varepsilon)^{K-k}\mu_0(\mathscr{B}_k\setminus\mathscr{B}_{k-1})+(1-\varepsilon)^{K}\mu_0(\mathscr{B}_0),
\end{equation*}
whereupon the conclusion follows.

Without loss of generality suppose that $j=N$ in the statement.
We proceed by induction over the number of measures $N$. 
Assume that for all $i, j\in[N-1]$ we have
\begin{equation*} 
\mathrm{supp}\left(\mu^i_0\right)\cap\mathrm{supp}\left(\mu^j_0\right)=\varnothing.
\end{equation*}
Let us prove that we can find a solution map $\Phi_{\text{fin}}:\mathscr{P}(\mathbb{S}^{d-1})\to \mathscr{P}(\mathbb{S}^{d-1})$ of \eqref{eq: cauchy.pb} such that
\begin{equation*}
    \mathrm{supp}\left(\Phi_{\text{fin}}(\mu^i_0)\right)\cap\mathrm{supp}\left(\Phi_{\text{fin}}(\mu^j_0)\right)=\varnothing
\end{equation*}
for all $i\neq j\in[N-1]$ and
\begin{align*}
    &\mathrm{supp}\left(\Phi_{\text{fin}}(\mu^i_0)\right)\cap\mathrm{supp}\left(\Phi_{\text{fin}}(\mu^N_0)\right)=\varnothing,\\
    &\mathrm{supp}\left(\Phi_{\text{fin}}(\mu^i_0)\right)\cap\mathrm{supp}\left(\Phi_{\text{fin}}(\nu_0)\right)=\varnothing
\end{align*}
for all $i\in[N-1]$. As done in previous proofs, we can take all time horizons to be as large as desired throughout by rescaling the norm of the parameters.


\subsubsection*{Step 1. Isolating $\mu_0^N$ and $\nu_0$}

Throughout this first step, $\bm{\mathit{W}}\equiv0$.
Consider $0<T_0<T_1<\ldots<T_{d-1}$ to be chosen later on, and set
\begin{equation*}
    \bm{\mathit{V}}(t)=\sum_{k=1}^{d-1}\alpha_k\alpha_k^\top 1_{[T_{k-1},T_k]}(t)
\end{equation*}
with $\{\alpha_k\}_{k\in[d-1]}$ being an orthonormal basis of $\mathrm{span }\left(\left\{\mathbb{E}_{\mu_0^N}[z]\right\}\right)^\perp$, namely 
$$\left \langle \mathbb{E}_{\mu_0^N}[x],\alpha_k\right\rangle=0$$ 
for all $k\in[d-1]$. We proceed recursively, starting from $k=1$. Observe that the solution to
\begin{equation} \label{eq: cauchy.pb.reloaded}
\begin{cases}  \partial_t\mu(t)+\mathrm{div}\left(\bm{\mathsf{P}}^\perp_x\left(\big\langle\alpha_1,\mathbb{E}_{\mu(t)}[x]\big\rangle \alpha_1\right)\mu(t)\right)=0 &\text{ on } \mathbb{R}_{\geqslant0}\times\mathbb{S}^{d-1},\\ 
\mu(0)=\mu_0 &\text{ on } \mathbb{S}^{d-1}
\end{cases}
\end{equation}
for $\mu_0\in\mathscr{P}(\mathbb{Q}_1^{d-1})$ satisfies
\begin{equation*}
    \frac{\, \mathrm{d}}{\, \mathrm{d} t}\left\langle\mathbb{E}_{\mu(t)}[x],\alpha_1\right\rangle =\left\langle\mathbb{E}_{\mu(t)}[x],\alpha_1 \right\rangle \left(1-\int\langle x',\alpha_1\rangle^2\mu(t, \, \mathrm{d} x')\right).
\end{equation*}
This implies
\begin{equation*}
    \left\langle\mathbb{E}_{\mu(t)}[x],\alpha_1\right\rangle=\left\langle\mathbb{E}_{\mu_0}[x],\alpha_1\right\rangle\mathrm{exp}\left(t-\int_0^t\int \langle x',\alpha_1\rangle^2 \mu(s, \, \mathrm{d} x') \, \mathrm{d} s\right).
\end{equation*} 
Therefore $\langle\mathbb{E}_{\mu(t)}[x],\alpha_1\rangle$ does not change sign along the trajectory $\mu(t)$, and also $\frac{\, \mathrm{d}}{\, \mathrm{d} t} \langle\mathbb{E}_{\mu(t)}[x],\alpha_1\rangle=0$ whenever $\mathbb{E}_{\mu_0}[x]$ is orthogonal to $\alpha_1$ or if $\mu(t)=\updelta_{\pm \alpha_1}$. Hence, for any $x(t)\in\mathrm{supp}(\mu(t))$,
\begin{equation*}
\frac{\, \mathrm{d}}{\, \mathrm{d} t} \langle x(t),\alpha_1\rangle =\left\langle \mathbb{E}_{\mu(t)}[x],\alpha_1 \right\rangle\left(1-\langle \alpha_1,x(t)\rangle^2\right)
\end{equation*}
which implies that 
\begin{equation*} 
    \lim_{t\to+\infty}x(t)=\pm \alpha_1
\end{equation*}
whenever  $\langle \mathbb{E}_{\mu_0}[x], \alpha_1\rangle \neq 0$. 
Therefore, for every $\varepsilon_1>0$ we can take $T_1>0$ large enough so that
\begin{equation*}
    \mathrm{supp}(\mu(T_1))\subset B(\alpha_1,\varepsilon_1)\cup B(-\alpha_1,\varepsilon_1)
\end{equation*}
whenever $\langle \mathbb{E}_{\mu_0}[x],\alpha_1\rangle \neq 0$. We can repeat the argument for every $k$ to deduce
\begin{equation}\label{eq: supports.in.balls}
    \mathrm{supp}(\mu(T_{d-1}))\subset \bigcup_{k\in[d-1]} B(\alpha_k,C_{k}\varepsilon_k)\cup B(-\alpha_k,C_{k}\varepsilon_k)
\end{equation}
where $C_k>0$  does not depend on $\varepsilon_k$, but does depend on  $\varepsilon_\ell$ for $\ell>k$. 
We can choose all radii $\varepsilon_k$ small enough so that
    \begin{equation}\label{eq: union.out}
        \bigcup_{k\in[d-1]} B(\alpha_k,C_{k}\varepsilon_k)\cup B(-\alpha_k,C_{k}\varepsilon_k)\subset\mathbb{S}^{d-1}\setminus\mathbb{Q}_1^{d-1}.
    \end{equation}
Whence we have constructed a map 
$$\Psi_{1}:\mathscr{P}(\mathbb{S}^{d-1})\to\mathscr{P}(\mathbb{S}^{d-1}),$$
with $\Psi_1(\mu_0)=\mu(T_d)$ where $\mu$ denotes the solution to the Cauchy problem \eqref{eq: cauchy.pb.reloaded} with the choice of parameters specified at the very beginning.  Since $\mathbb{E}_{\mu_0^i}[x]$ is not colinear with $\mathbb{E}_{\mu_0^N}[x]$, and thanks to \eqref{eq: supports.in.balls} and \eqref{eq: union.out},
$$\mathrm{supp}\,\Psi_1(\mu^j_0)\subset\mathbb{S}^{d-1}\setminus\mathbb{Q}_1^{d-1}$$ for $j\in[N-1]$, and 
$$\Psi_1(\mu^N_0)=\mu^N_0,\hspace{1cm} \Psi_1(\nu_0)=\nu_0.$$

\subsubsection*{Step 2. Clustering the supports of $\mu_0^N$ and $\nu_0$}

Let $a\in\mathbb{S}^{d-1}$ and $\underline{b}\in\mathbb{R}$ be such that 
    \begin{align*}
    \langle a,x\rangle +\underline{b}&>0\hspace{1cm}\text{ for }x\in \mathbb{Q}_1^{d-1}\\
\langle a,x\rangle +\underline{b}&<0\hspace{1cm}\text{ for }x\in \bigcup_{k\in[d-1]} B(\alpha_k,C_k\varepsilon_k)\cup B(-\alpha_k, C_k\varepsilon_k).
\end{align*}
For instance, this can be ensured by taking $\{\varepsilon_k\}_{k\in[d-1]}$ small enough and setting 
\begin{equation*}
    a=\frac{\mathbb{E}_{\mu_0^N}[x]}{\|\mathbb{E}_{\mu_0^N}[x]\|} \hspace{1cm}\text{ and } \hspace{1cm} b=- \max_{k\in[d-1]} C_k\varepsilon_k.
\end{equation*} 
Let $\delta>0$ be arbitrary; in the interval $(T_{d},T_\delta)$, for $T_\delta>0$ to be determined later on, consider 
\begin{align*}
\bm{\mathit{W}}(t)&=\bm{\mathit{W}}_2\cdot 1_{[T_d,T_\delta]}(t) &
\bm{\mathit{U}}(t)&=\bm{\mathit{U}}\cdot 1_{[T_d,T_\delta]}(t),\\
b(t)&=\underline{b}{\bf1}\cdot 1_{[T_d,T_\delta]}(t), &
\bm{\mathit{U}}&\equiv{\bf1}a^\top,
\end{align*}
where $\bm{\mathit{W}}_2$ is any $d\times d$ matrix such that
\begin{equation*}
    \bm{\mathit{W}}_2 {\bf1}= \mathbb{E}_{\mu_0^N}[x].
\end{equation*}
For this choice of parameters, the measures $\mu^i(T_d)$, for $i\in[N-1]$, are invariant by the corresponding flow map of \eqref{eq: cauchy.pb}. We can choose $T_\delta>0$ large enough so that
\begin{equation} \label{eq: inclusion}
\mathrm{supp}\left(\nu(T_\delta)\right)\cup\mathrm{supp}\left(\mu^N(T_\delta)\right)\subset B\left(  \frac{\mathbb{E}_{\mu_0^N}[x]}{\|\mathbb{E}_{\mu_0^N}[x]\|},\delta\right).
\end{equation}
This follows by observing that 
\begin{equation*}
\lim_{t\to+\infty}\left\langle x(t),\frac{\mathbb{E}_{\mu_0^N}[x]}{\|\mathbb{E}_{\mu_0^N}[x]\|}\right\rangle =1    
\end{equation*}
for every $x_0\in\mathrm{supp}(\mu_0^N)$, where $x(t)$ follows the characteristics of \eqref{eq: cauchy.pb}, by following the same arguments as for \eqref{eq: dissipation.sphere} in the proof of \Cref{lem: two.balls}, or \eqref{eq: Hartman.Grobman} in the proof of \Cref{lem: induction.neural.ode}.
This construction yields a flow map 
$$\Psi_2:\mathscr{P}(\mathbb{S}^{d-1})\to\mathscr{P}(\mathbb{S}^{d-1}),$$ 
with 
$$\Psi_2(\mu_0)=\mu(T_\delta)$$
where $\mu$ denotes the solution to the Cauchy problem \eqref{eq: cauchy.pb} on $[T_d, T_\delta]$ with the choice of parameters specified in this step, which satisfies 
$$\Psi_2(\mu^j(T_d))=\mu^j(T_d)$$ for $j\in[N-1]$,
and $\Psi_2(\mu^N(T_d)),\Psi_2(\nu(T_d))$
satisfy \eqref{eq: inclusion}.


\subsubsection*{Step 3. Flow reversal}

We finally employ the inverse map $\Psi_{1}^{-1}$, and choose $\delta>0$ small enough to obtain the result; namely setting $\Phi_{\text{fin}}:=\Psi_1^{-1}\circ\Psi_2\circ\Psi_1$, 
we have
\begin{equation*}
    \Phi_{\text{fin}}(\mu_0^i)=\mu_0^i
\end{equation*}
for $i\in[N-1]$, and
\begin{equation*}
    \mathrm{supp}(\Phi_{\text{fin}}(\nu_0))\cup\mathrm{supp}(\Phi_{\text{fin}}(\mu_0^N))\subset B\left( \frac{\mathbb{E}_{\mu_0^N}[x]}{\|\mathbb{E}_{\mu_0^N}[x]\|} , C_T\delta\right),
\end{equation*}
for some $C_T>0$ depending on $\Psi_1$ but not on $\Psi_2$. Therefore, by choosing $\delta>0$ small enough, we can conclude.

\begin{align*}
    \langle a,x\rangle +\underline{b}&>0\hspace{1cm}\text{ for }x\in \mathbb{Q}_1^{d-1}\\
\langle a,x\rangle +\underline{b}&<0\hspace{1cm}\text{ for }x\in \bigcup_{k\in[d-1]} B(\alpha_k,C_k\varepsilon_k)\cup B(-\alpha_k, C_k\varepsilon_k).
\end{align*}

We begin with the first part of the statement. As before, we can take all time horizons to be as large as desired throughout by rescaling the norm of the parameters.

\subsubsection*{Part 1.}
There exists an open ball $\mathscr{B}\subset \mathrm{supp}(\mu_0)\cup\mathrm{supp}(\nu_0)$ such that
\begin{equation*}
\mu_0(\mathscr{B})\neq\nu_0(\mathscr{B}).
\end{equation*}
We now claim that there exists some $x^*\in\mathscr{B}$ such that 
\begin{equation*}
\mu_0(\mathscr{B})x^*+\int_{\mathbb{S}^{d-1}\setminus \mathscr{B}}x \mu_0(\, \mathrm{d} x)\neq \nu_0(\mathscr{B})x^*+\int_{\mathbb{S}^{d-1}\setminus\mathscr{B}}x \nu_0(\, \mathrm{d} x).
\end{equation*}
Indeed if this were to be false, then we'd have 
\begin{equation*}
x^*=\frac{1}{\mu_0(\mathscr{B})-\nu_0(\mathscr{B})}\int_{\mathbb{S}^{d-1}\setminus\mathscr{B}} x(\nu_0(\, \mathrm{d} x)-\mu_0(\, \mathrm{d} x))
\end{equation*}
for all $x^*\in\mathscr{B}$, which cannot hold. Take $x^*\in \mathscr{B}$ as above. 
Let $a\in\mathbb{S}^{d-1}$ be the center of $\mathscr{B}$ and $R>0$ its radius. 
Consider
\begin{align} \label{eq: controls.1}
\bm{\mathit{U}} &= -{\bf1}a^\top,\\ 
b&= R {\bf1}, \nonumber
\end{align}
and any $\bm{\mathit{W}}\in\mathscr{M}_{d\times d}(\mathbb{R})$ satisfying
\begin{equation} \label{eq: controls.2}
\bm{\mathit{W}} {\bf1}=x^*.
\end{equation}
Then, by \Cref{lem: two.balls}, for any $\varepsilon>0$ we can take a large enough $T>0$ such that the solution to
\begin{equation*}
\begin{cases}
\partial_t \mu(t)+\mathrm{div}\left(\bm{\mathsf{P}}^\perp_x\Big(\bm{\mathit{W}}(\bm{\mathit{U}} x+b)_+\Big)\mu(t)\right)=0 &\text{ on } \mathbb{R}_{\geqslant0}\times\mathbb{S}^{d-1}\\
\mu(0)=\mu_0 &\text{ on } \mathbb{S}^{d-1}
\end{cases}
\end{equation*}
satisfies
\begin{equation*}
\mathsf{W}_2(\mu(T),\alpha)\leqslant\varepsilon
\end{equation*}
where
\begin{equation*}
\alpha(A)=\mu_0(\mathscr{B})\updelta_{x^*}(A\setminus\mathscr{B})+\mu_0(A\setminus\mathscr{B})
\end{equation*}
for any Borel $A\subset\mathbb{S}^{d-1}$.
Since the expectation of a measure is continuous with respect to the measure in the sense of the Wasserstein distance, it follows that there is a Lipschitz invertible flow map $\Phi:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ of \eqref{eq: neural.ode.sphere} such that $\mathbb{E}_{\Phi_\#\mu_0}[x]\neq\mathbb{E}_{\Phi_\#\nu_0}[x]$. Furthermore, $\Phi(x)=x$ for $x\notin\mathscr{B}$ by construction.

\subsubsection*{Part 2.}
The parameters take the form
\begin{align*}
\bm{\mathit{V}}(t)&= I_d 1_{[0,T_*]}(t) & 
\bm{\mathit{W}}(t)&= \bm{\mathit{W}} 1_{[T_*,T]}(t) \\
\bm{\mathit{U}}(t)&= \bm{\mathit{U}} 1_{[T_*,T]}(t) &
b(t)&=b 1_{[T_*,T]}(t),
\end{align*}
for $T_*>0$ and $T>T_*$ to be determined later on. Recall that $\bm{\mathit{B}}\equiv0$. We first prove that if
\begin{equation}\label{eq: diff.support}
\mathrm{supp}(\mu_0)\neq\mathrm{supp}(\nu_0)
\end{equation}
is not satisfied, it ought to hold after some time. 
Indeed, suppose that \eqref{eq: diff.support} does not hold. 
Let $\tau>0$ be arbitrary.
For any $x_0\in \partial\mathrm{conv}_g \mathrm{supp}(\mu_0))\cap \mathrm{supp}(\mu_0)$ consider
\begin{equation*}
\begin{cases}
\dot{x}(t)=\mathbb{E}_{\mu(t)}[x]-\left\langle \mathbb{E}_{\mu(t)}[x],x(t)\right\rangle x(t)&\text{ in }  [0,\tau]\\
x(0)=x_0
\end{cases}
\end{equation*}
and
\begin{equation*}
\begin{cases}
\dot{y}(t)=\mathbb{E}_{\nu(t)}[x]-\left\langle \mathbb{E}_{\nu(t)}[x],y(t)\right\rangle y(t) &\text{ in }  [0,\tau]\\
y(0)=x_0.
\end{cases}
\end{equation*}
Taylor-expanding within the Duhamel formula, for $\tau$ small enough, we find 
\begin{equation*}
x(\tau)=x_0+\tau\left(\mathbb{E}_{\mu_0
}[x]-\left\langle\mathbb{E}_{\mu_0}[x],x_0\right\rangle x_0\right)+O(\tau^2)
\end{equation*}
and
\begin{equation*}
y(\tau)=x_0+\frac{\tau}{\gamma_1}\left(\mathbb{E}_{\mu_0
}[x]-\left\langle \mathbb{E}_{\mu_0}[x],x_0\right\rangle x_0\right)+O(\tau^2)
\end{equation*}
Then
\begin{equation*}
\left\langle y(\tau)-x(\tau),\frac{\mathbb{E}_{\mu_0}
[x]}{\|\mathbb{E}_{\mu_0
}[x]\|}\right\rangle=\tau\left(\frac{1}{\gamma_1}-1\right)\left(\|\mathbb{E}_{\mu_0}[x]\|-\frac{\langle \mathbb{E}_{\mu_0}[x],x_0\rangle^2}{\|\mathbb{E}_{\mu_0}[x]\|}\right)+O(\tau^2).
\end{equation*}
Suppose\footnote{If $\upsigma_d(\mathrm{conv}_g\,\mathrm{supp}(\mu_0))=0$, we can argue as in the proof of \Cref{prop: targets.atoms}, reducing the dynamics to $\mathbb{S}^{d-2}$ (or a lower-dimensional sphere), where the same proof can be repeated.}  $\upsigma_d(\mathrm{conv}_g \,\mathrm{supp}(\mu_0))>0$.
Since $x_0\in\partial\mathrm{conv}_g\,\mathrm{supp}(\mu_0)$ as well as $\frac{\mathbb{E}_{\mu_0}[x]}{\|\mathbb{E}_{\mu_0}[x]\|}\in \mathrm{int }(\mathrm{ conv}_g\,\mathrm{supp}(\mu_0))$,
\begin{equation*}
    \|\mathbb{E}_{\mu_0}[x]\|-\frac{\langle \mathbb{E}_{\mu_0}[x],x_0\rangle^2}{\|\mathbb{E}_{\mu_0}[x]\|}\geqslant c
\end{equation*}
for some $c>0$. Since $\gamma_1\in(0,1)$ we gather that
\begin{equation*}
\left\langle y(\tau)-x(\tau),\frac{\mathbb{E}_{\mu_0}
[x]}{\|\mathbb{E}_{\mu_0
}[x]\|}\right\rangle>c_1\tau+O(\tau^2)>0
\end{equation*}
for some $c_1>0$ and for $\tau$ small enough.
Consequently for $T_*$ small enough, we {have
$\mathrm{supp}(\nu(T_*))\subset\mathrm{supp}(\mu(T_*))$} as well as $\mathrm{supp}(\mu(T_*))\neq \mathrm{supp}(\nu(T_*))$. Therefore, there exist $\varepsilon>0$ and an open ball $\mathscr{B}$ such that
    \begin{equation}\label{eq: discriminatory.ball}
        \mathscr{B}\cap\mathrm{supp}(\nu(T_*))\neq \varnothing,\quad \mathscr{B}\cap \mathrm{supp}(\mu(T_*))=\varnothing
    \end{equation}
and
\begin{equation*}
    \mathscr{B}\subset \left\{ x\in \mathbb{S}^{d-1}: \quad \inf_{y\in \mathrm{conv}_g(\mu(T_*))}d_g(x,y)\leqslant \varepsilon\right\}.
\end{equation*}

    Let $a\in \mathbb{S}^{d-1}$ be the center of $\mathscr{B}$ and $R$ be its radius. Now, in the interval $(T_*,T)$ we take $\bm{\mathit{V}}\equiv0$ and $\bm{\mathit{W}},\bm{\mathit{U}}\in \mathscr{M}_{d\times d}(\mathbb{R})$ and $b\in \mathbb{R}^d$ as in \eqref{eq: controls.1}--\eqref{eq: controls.2}



    for some $x^*\in \mathscr{B}$ to be determined later on.  Because of \eqref{eq: discriminatory.ball}, $\nu$ is invariant with respect to the flow generated by the parameters defined in \eqref{eq: controls.1} and \eqref{eq: controls.2}. 
     We change the coordinate system so that
    \begin{equation*}
        \left(\int_{\mathbb{S}^{d-1}} x\nu(T_*)\right)_1=\alpha,\quad \left(\int_{\mathbb{S}^{d-1}} x\nu(T_*)\right)_k=0\quad \text{ for }k\geqslant 2.
    \end{equation*}
    Using the fact that $\mathscr{B}$ is open {and \eqref{eq: discriminatory.ball}}, it is impossible that for every $x^*\in \mathscr{B}$,
    \begin{equation*}
        \left(\int_{\mathbb{S}^{d-1}\setminus\mathscr{B}} x\,\mu(T_*)\right)_2+\mu(T_*, \mathscr{B})(x^*)_2=0.
    \end{equation*}
    Consequently there exist $x^*\in \mathscr{B}$ for which 
\begin{equation*}
    \int_{\mathbb{S}^{d-1}\setminus\mathscr{B}} x\,\mu(T_*)+\mu(T_*, \mathscr{B})x^* \hspace{1cm}\text{ and } \hspace{1cm}\int_{\mathbb{S}^{d-1}} x\nu(T_*)
\end{equation*}
are not colinear. Therefore, letting $T$ large enough, by the same arguments as in \Cref{lem: perturbation} {and since $\mathscr{B}\subset \mathrm{conv}_g\,\mathrm{supp}(\mu_0)\cup \mathrm{conv}_g\,\mathrm{supp}(\nu_0)$}, we can conclude.


Since the vector field in \eqref{eq: cauchy.pb} (or \eqref{eq: average.vf}) is Lipschitz, for every $i\in[N]$ there exist  Lipschitz-continuous and invertible maps $\mathsf{T}^i_{\Phi_1}:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ and $\mathsf{T}^i_{\Phi_3}:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ such that
\begin{equation*}
    \Phi_1(\mu_0^i)=\left(\mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i,
\end{equation*}
and
\begin{equation*}
    \Phi_3(\mu_1^i)=\left(\mathsf{T}^i_{\Phi_3}\right)_\#\mu_1^i.
\end{equation*}
Then
\begin{equation}\label{eq: separated}
    \mathrm{supp}\left(\left(\mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i\right)\cap \mathrm{supp}\left(\left(\mathsf{T}^j_{\Phi_1}\right)_\#\mu_0^j\right)=\varnothing,
\end{equation}
and
\begin{equation*}
    \mathrm{supp}\left(\left(\mathsf{T}^i_{\Phi_3}\right)_\#\mu_1^i\right)\cap \mathrm{supp}\left(\left(\mathsf{T}^j_{\Phi_3}\right)_\#\mu_1^j\right)=\varnothing
\end{equation*}
for $i\neq j\in[N]$. We wish to find an integrable map $\Psi^i:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ that satisfies
\begin{equation*}
     \left(\Psi^i\circ\mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i= \left(\mathsf{T}^i_{\Phi_3}\right)_\#\mu_1^i.
\end{equation*}
Using \eqref{eq: hypothesis}, since $\mathsf{T}^i_{\Phi_1}$ and $\mathsf{T}^i_{\Phi_1}$ are bijective, this is equivalent to 
\begin{equation*}
    \left(\mathsf{T}^i_{\Phi_3}\right)^{-1}\circ\Psi^i\circ\mathsf{T}^i_{\Phi_1} =\mathsf{T}^i,
\end{equation*}
so
\begin{equation*}
\Psi^i=\mathsf{T}^i_{\Phi_3}\circ\mathsf{T}^i\circ\left(\mathsf{T}^i_{\Phi_1}\right)^{-1}.
\end{equation*}
Due to \eqref{eq: separated}, there also exists a Lipschitz-continuous map $\Psi:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ satisfying \eqref{eq: diffeo.supports}.

Consider
\begin{equation} \label{eq: simple.function}
    \Psi^\dagger_\varepsilon(x):=\sum_{m=1}^{M(\varepsilon)} y_m^\varepsilon 1_{\Omega_m(\varepsilon)}(x),
\end{equation}
where $\Omega_m(\varepsilon)\subset\mathbb{S}^{d-1}$ are connected and pairwise disjoint with 
\begin{equation}\label{eq: partition}
    \bigcup_{m\in[M(\varepsilon)]} \Omega_m(\varepsilon) = \mathbb{S}^{d-1},
\end{equation}
whereas $y_m^\varepsilon\neq y_{m'}^\varepsilon$ when $m\neq m'$, and
\begin{equation}\label{eq: approx.by.simple.function}
    \left\|\Psi^\dagger_\varepsilon-\Psi\right\|_{L^2(\mu)}\leqslant \frac{\varepsilon}{2}.
\end{equation}
Our goal is then to approximate $\Psi^\dagger_\varepsilon$ by means of some flow map $\Psi_\varepsilon:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ of \eqref{eq: neural.ode.sphere}. To this end, we also approximate $\mu$ as
\begin{equation*} 
   \left|\mu(\mathbb{S}^{d-1})-\mu^\eta(\mathbb{S}^{d-1})\right|\leqslant\eta,
\end{equation*}
with $\mu^\eta$ curated so that we can apply \Cref{prop: interpolation.neural.ode} and \Cref{prop: compression} ``more easily''. Then,
\begin{align}
    \int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu(\, \mathrm{d} x)&=\int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu^\eta(\, \mathrm{d} x)\nonumber\\
    &+\int\left\|\Psi_\varepsilon(x)-\Psi^\dagger_\varepsilon(x)\right\|^2(\mu(\, \mathrm{d} x)-\mu^\eta(\, \mathrm{d} x))\nonumber\\
    &\hspace{-0.5cm}\leqslant \int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu^\eta(\, \mathrm{d} x)+2\pi\eta. 
    \label{eq: TV.implication}
\end{align}

\subsubsection*{Step 1: Constructing $\mu^\eta$}

Fix $\eta>0$. By the Lebesgue decomposition theorem, we split $\mu$ into purely atomic and diffusive parts:
\begin{equation*}
    \mu=\mu_{\text{pp}}+\mu_{\text{diff}},
\end{equation*}
with $\mu_{\text{diff}}$ having no atoms, and\footnote{Recall that the atomic part of any $\sigma$-finite measure is always a countable set.}
\begin{equation*}
\mu_{\text{pp}}=\sum_{n=1}^{\infty}\mu(\{x_n\})\updelta_{x_n}.
\end{equation*}
Let $N(\eta)\geqslant1$ be such that
\begin{equation*} 
    \mu_{\text{pp}}^\eta :=\sum_{n=1}^{N(\eta)}\mu(\{x_n\})\updelta_{x_n}
\end{equation*}
satisfies
\begin{equation*}
    \mu_{\text{pp}}(A)-\mu_{\text{pp}}^\eta(A)\leqslant\frac{\eta}{2}
\end{equation*}
for any Borel $A\subset\mathbb{S}^{d-1}$. 
Fix $\eta_1>0$ to be determined later on but such that for all $n\in[N(\eta)]$,
\begin{equation} \label{eq: balls.small}
    B(x_n,\eta_1)\cap B(x_m,\eta_1)=\varnothing \hspace{1cm} \text{ for } m\neq n\in[N(\eta)].
\end{equation}
Consider
\begin{equation}\label{eq: Lebesgue.decomp}
    \mu^\eta:=\mu_{\text{pp}}^\eta+\mu_{\text{diff}}^\eta,
\end{equation}
where\footnote{In case $\mu_{\text{pp}}=0$, we consider an arbitrary point $x_1\in\mathbb{S}^{d-1}$ and then define 
\begin{equation*}
    \mu_{\text{diff}}^{\eta}(A):=\mu_{\text{diff}}\left(A\setminus B(x_1,\eta_1)\right).
\end{equation*}}
\begin{equation} \label{eq: removing.mass.from.mu}
    \mu_{\text{diff}}^{\eta}(A):=\mu_{\text{diff}}\left(A\setminus \bigcup_{n\in[N(\eta)]} B(x_n,\eta_1)\right)
\end{equation}
for any Borel $A\subset \mathbb{S}^{d-1}$. Furthermore, take $\eta_1>0$ small enough so that, in addition to \eqref{eq: balls.small},
\begin{equation*} 
    \left|\mu(\mathbb{S}^{d-1})-\mu^\eta(\mathbb{S}^{d-1})\right|\leqslant\eta.
\end{equation*}

\subsubsection*{Step 2: Toward a sufficient matching problem}

We further decompose $\mu^\eta$ in several parts. For $m\in[M(\varepsilon)]$, consider 
\begin{equation}\label{eq: mu.m}
    \mu_m(A):=\mu^\eta_{\text{diff}}(A\cap\Omega_m)
\end{equation}
for any Borel $A\subset \mathbb{S}^{d-1}$. 
Because of \eqref{eq: removing.mass.from.mu}, \eqref{eq: mu.m} and \eqref{eq: partition}, we have
\begin{equation} \label{eq: mu.eta.mu.m}
    \mu^\eta_{\mathrm{diff}}(A) = \sum_{m=1}^{M(\varepsilon)} \mu_m(A)
\end{equation}
for any Borel $A\subset \mathbb{S}^{d-1}$. Therefore, thanks to \eqref{eq: Lebesgue.decomp} and \eqref{eq: mu.eta.mu.m}, bounding \eqref{eq: TV.implication} boils down to bounding
\begin{align}
    &\int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu^\eta(\, \mathrm{d} x)\nonumber\\
    &=\sum_{m=1}^{M(\varepsilon)}\int\left\|\Psi_\varepsilon(x)-y_m^\varepsilon\right\|^2\mu_m+\sum_{n=1}^{N(\eta)}\mu(\{x_n\})\left\|\Psi_\varepsilon(x_n)-\Psi^\dagger_\varepsilon(x_n)\right\|^2.\label{eq: new.bound}
\end{align}
For the second term in \eqref{eq: new.bound} we will employ exact matching via \Cref{prop: interpolation.neural.ode}, whereas for the first, we first note that for any $\eta_3>0$, one has the  trivial identity
\begin{align}
    &\int\left\|\Psi_\varepsilon(x)-y_m^\varepsilon\right\|^2\mu_m(\, \mathrm{d} x)\nonumber\\
    &=\mu_m(\mathbb{S}^{d-1})\Bigg(\int_{(\Psi_\varepsilon)^{-1}(B(x_m,\eta_3))} \|\Psi_\varepsilon(x)-y_m^\varepsilon\|^2\frac{\mu_m(\, \mathrm{d} x)}{\mu_m(\mathbb{S}^{d-1})}\nonumber\\&\hspace{2cm}+\int_{(\Psi_\varepsilon)^{-1}(B(x_m,\eta_3))^c} \|\Psi_\varepsilon(x)-y_m^\varepsilon\|^2\frac{\mu_m(\, \mathrm{d} x)}{\mu_m(\mathbb{S}^{d-1})}\Bigg)\label{eq: trivial.split}.
\end{align}
We use the following.

\begin{claim}\label{cl: W.to.ball}
Suppose $\mu\in\mathscr{P}(\mathbb{S}^{d-1})$ and $x_0\in \mathbb{S}^{d-1}$  satisfy
\begin{equation*}
    \mathsf{W}_2(\mu,\updelta_{x_0})\leqslant\eta_2.
\end{equation*}
Then there exists some numerical constant $C>0$ (not depending on $\eta_2$) such that
\begin{equation*}
    1-\mu(B(x_0,\eta_3))\leqslant C\cdot\frac{\eta_2}{\eta_3}
\end{equation*}
for all $\eta_3>0$.
\end{claim}

\begin{proof}[Proof of Claim 1.]
By compactness of $\mathbb{S}^{d-1}$ and Kantorovich-Rubinstein duality,
\begin{equation*}
   \mathsf{W}_1(\mu,\updelta_{x_0})=\sup_{\mathrm{Lip}(g)\leqslant 1}\int g(\mu -\updelta_{x_0} )\leqslant C\cdot\eta_2
\end{equation*}
for some numerical constant $C>0$.
Hence, for $g:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ defined as 
\begin{equation*}
    g(x)=\begin{cases}
        1\quad &x\in B(x,\eta_3)\\
        1-\frac{1-\eta_3}{\eta_3}\quad &x\in B(x,\eta_3)\cap B(x,2\eta_3)\\
        0\quad &x\notin B(x,2\eta_3),
    \end{cases}
\end{equation*}
we obtain
\begin{equation*}
    1-\mu(B(x,\eta_3))\leqslant C\cdot\frac{\eta_2}{\eta_3}.\qedhere
\end{equation*}
\end{proof}

From \eqref{eq: trivial.split}, if 
\begin{equation*} 
 \mathsf{W}_2(\mu_m,\updelta_{
y^\varepsilon_m})\leqslant \eta_2   
\end{equation*}
were to hold, by applying \Cref{cl: W.to.ball} one would find
\begin{equation}\label{eq: estimate.in.m}
    \int\left\|\Psi_\varepsilon(x)-y_m\right\|^2\mu_m(\, \mathrm{d} x)\leqslant\mu_m(\mathbb{S}^{d-1})\left(\eta_3^2+2\pi\cdot  C\cdot \frac{\eta_2}{\eta_3}\right).
\end{equation}
\eqref{eq: new.bound} and \eqref{eq: estimate.in.m} naturally raise the following problem: find a flow map that matches
\begin{align*}
    \left(\mu_m,\mu_m(\mathbb{S}^{d-1})\updelta_{y_m}\right)  &\quad\text{ for } m\in[M(\varepsilon)],\\ 
    \left(\mu(\{x_n\})\updelta_{x_n},\mu(\{x_n\})\updelta_{\Psi^\dagger_\varepsilon(x_n)}\right) &\quad\text{ for } n\in[N(\eta)].
\end{align*}
We aim for the matching to be exact for the discrete input measures (second line) and approximate in $\mathsf{W}_2$ for the diffuse ones (first line).

\subsubsection*{Step 3: Constructing $\Psi_\varepsilon$ through matching}
We look to use \Cref{prop: compression} to cluster the diffuse input measures to a single atom, which paired with \Cref{prop: targets.atoms} for matching all atoms approximately, would lead to the desired conclusion. 
Specifically, we construct the approximation candidate $\Psi_\varepsilon:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ as
\begin{equation}\label{eq: final.flow}
    \Psi_\varepsilon:=\Phi_3\circ \Phi_2\circ \Phi_1,
\end{equation}
where
\begin{itemize}

    \item $\Phi_1:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ is the flow map induced by \Cref{prop: interpolation.neural.ode}\footnote{Should the assumption in \Cref{prop: interpolation.neural.ode} not hold, one can always choose slightly different \(y_m^\varepsilon\) in \eqref{eq: simple.function} so that the approximation error is not altered and the assumption does hold.}, which exactly matches $\mu(\{x_n\})\updelta_{x_n}$ to $\mu(\{x_n\})\updelta_{\Psi^\dagger_\varepsilon(x_n)}$, for all $n\in[N(\eta)]$;
    \item $\Phi_2:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ is the flow map induced by \Cref{prop: compression} that concentrates $\mu_m$ near some atom inside $\mathrm{supp}(\Phi_{1\#}\mu_m)$, for all $m\in[M(\varepsilon)]$;
    \item $\Phi_3:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ is the flow map induced by \Cref{prop: interpolation.neural.ode} that matches the atoms from the previous step to $\mu_m(\mathbb{S}^{d-1})\updelta_{y_m^\varepsilon}$, for all $m\in[M(\varepsilon)]$.

\end{itemize}
We now make the construction of \eqref{eq: final.flow} precise, and with the help of \eqref{eq: estimate.in.m}, \Cref{prop: compression}, and \Cref{prop: interpolation.neural.ode}, we bound the right hand side in \eqref{eq: new.bound}.
\begin{enumerate}
    \item Thanks to \Cref{prop: interpolation.neural.ode} we have
\begin{equation*}
\Phi_{1\#}\mu^\eta_{\text{pp}}=\Psi^\dagger_{\varepsilon\#} \mu^\eta_{\text{pp}}.
\end{equation*}
Exact matching ensures
\begin{equation}\label{eq: first.flow.discrete}
    \sum_{n=1}^{N(\eta)} \mu(\{x_n\})\left\|\Phi_1(x_n)-\Psi^\dagger_\varepsilon(x_n)\right\|^2=0.
\end{equation}
\item We apply \Cref{prop: compression} to the measures $(\Phi_{1\#}\mu_m)_{m\in[M(\varepsilon)]}$ to deduce that, for all $m\in[M(\varepsilon)]$,
\begin{equation*}
\mathsf{W}_2\left(\Big(\Phi_2\circ\Phi_1\Big)_{\#}\frac{\mu_m}{ \mu_m(\mathbb{S}^{d-1})}, \updelta_{x_{m}}\right)\leqslant \eta_2
\end{equation*}
for some $x_{m}\in \mathrm{supp}(\Phi_{1\#}\mu_m)$ and for small enough $\eta_2>0$ to be determined later on. Note that when we apply \Cref{prop: compression} for each $m$ in view of clustering $\Phi_{1\#}\mu_m$ to a discrete measure supported inside $\mathrm{supp}(\Phi_{1\#}\mu_m)$, the flow map stemming from \Cref{prop: compression} also satisfies---because of how \Cref{lem: tubular.mass.movement} is applied in the proof of \Cref{prop: compression}---
\begin{equation}\label{eq: identity.flow.2}
\Phi_2\bigg|_{\left(\mathbb{S}^{d-1}\setminus\bigcup_{m\in[M(\varepsilon)]} \mathrm{supp}(\Phi_{1\#}\mu_m)\right)}\equiv\mathrm{Id}.
\end{equation}
Then, by the continuity of the flow map $\Phi_1$, and \eqref{eq: removing.mass.from.mu},
we have 
$$
\mathrm{supp}\left(\Phi_{1\#}\mu_{\text{pp}}^\eta\right)\subset \mathbb{S}^{d-1}\setminus\left(\,\bigcup_{m\in[M(\varepsilon)]}\mathrm{supp}(\Phi_{1\#}\mu_m)\,\right),
$$
and from \eqref{eq: identity.flow.2}
\begin{equation*}
    \Big(\Phi_2\circ\Phi_1\Big)_\#\mu^\eta_{\text{pp}} =\Psi^\dagger_{\varepsilon\#}\mu^\eta_{\text{pp}}.
\end{equation*}
This means that, paired with \eqref{eq: first.flow.discrete}, we also have
\begin{equation*} 
    \sum_{n=1}^{N(\eta)} \mu(\{x_n\})\left\|(\Phi_2\circ\Phi_1)(x_n)-\Psi^\dagger_\varepsilon(x_n)\right\|^2=0.
\end{equation*}

\item  We then apply \Cref{prop: interpolation.neural.ode} to find a flow map $\Phi_3$ which matches the pairs $(x_m,y_m)_{m\in[M(\varepsilon)]}$, and leads us to deduce, by virtue of continuity with respect to the data of \eqref{eq: neural.pde.sphere}, that
\begin{equation}\label{eq: close.in.W2}
\mathsf{W}_2\left(\Big(\Phi_3\circ\Phi_2\circ\Phi_1\Big)_{\#}\frac{\mu_m}{\mu_m(\mathbb{S}^{d-1})}  ,\updelta_{y_m^\varepsilon}\right)\leqslant C_{M(\varepsilon)}\cdot \eta_2
\end{equation}
holds for some $C_{M(\varepsilon)}>0$ independent of $\eta$. Moreover, after applying $\Phi_3$, thanks to \Cref{prop: interpolation.neural.ode} (or \Cref{lem: induction.neural.ode}), we have that the pure point part remains unaltered:
\begin{equation*}
    \Big(\Phi_3\circ\Phi_2\circ\Phi_1\Big)_\# \mu^\eta_{\text{pp}} =\Psi^\dagger_{\varepsilon\#}\mu^\eta_{\text{pp}}.
\end{equation*}
Hence,
\begin{equation*}
    \sum_{n=1}^{N(\eta)} \mu(\{x_n\})\left\|\Psi_\varepsilon(x_n)-\Psi^\dagger_\varepsilon(x_n)\right\|^2=0.
\end{equation*}


\end{enumerate}

 \subsubsection*{Step 4: Putting everything together}
 Thanks to \eqref{eq: estimate.in.m} and \eqref{eq: close.in.W2}, for any $\varepsilon_1>0$ we can choose $\eta_2$ and $\eta_3$ small enough as to ensure
\begin{equation*}
    \int\|\Psi_\varepsilon(x)-y_m^\varepsilon\|^2\mu_m(\, \mathrm{d} x)\leqslant\mu_m(\mathbb{S}^{d-1})\varepsilon_1.
\end{equation*}
Since $\sum_{m\in[M(\varepsilon)]} \mu_m(\mathbb{S}^{d-1})\leqslant 1$ by construction,
\begin{equation*}
    \sum_{m=1}^{M(\varepsilon)} \int\|\Psi_\varepsilon(x)-y_m^\varepsilon\|^2\mu_m(\, \mathrm{d} x)\leqslant \varepsilon_1.
\end{equation*}
Combining all the estimates, and choosing $\varepsilon_1$ and $\eta$ small enough, we can deduce that
\begin{equation*}
    \left\|\Psi_\varepsilon-\Psi^\dagger_\varepsilon\right\|^2_{L^2(\mu)}=\int\left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon1_{\Omega_m}\right\|^2\mu(\, \mathrm{d} x)\leqslant \varepsilon_1+2\pi\cdot\eta\leqslant\frac{\varepsilon^2}{4},
\end{equation*}
which paired with \eqref{eq: approx.by.simple.function} leads us to the conclusion.

\begin{align}
    \int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu(\, \mathrm{d} x)&=\int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu^\eta(\, \mathrm{d} x)\nonumber\\
    &+\int\left\|\Psi_\varepsilon(x)-\Psi^\dagger_\varepsilon(x)\right\|^2(\mu(\, \mathrm{d} x)-\mu^\eta(\, \mathrm{d} x))\nonumber\\
    &\hspace{-0.5cm}\leqslant \int \left\|\Psi_\varepsilon(x)-\sum_{m=1}^{M(\varepsilon)}y_m^\varepsilon 1_{\Omega_m}\right\|^2\mu^\eta(\, \mathrm{d} x)+2\pi\eta. 
    \label{eq: TV.implication}
\end{align}

\begin{equation} \label{eq: balls.small}
    B(x_n,\eta_1)\cap B(x_m,\eta_1)=\varnothing \hspace{1cm} \text{ for } m\neq n\in[N(\eta)].
\end{equation}

\label{cl: W.to.ball}
Suppose $\mu\in\mathscr{P}(\mathbb{S}^{d-1})$ and $x_0\in \mathbb{S}^{d-1}$  satisfy
\begin{equation*}
    \mathsf{W}_2(\mu,\updelta_{x_0})\leqslant\eta_2.
\end{equation*}
Then there exists some numerical constant $C>0$ (not depending on $\eta_2$) such that
\begin{equation*}
    1-\mu(B(x_0,\eta_3))\leqslant C\cdot\frac{\eta_2}{\eta_3}
\end{equation*}
for all $\eta_3>0$.

By compactness of $\mathbb{S}^{d-1}$ and Kantorovich-Rubinstein duality,
\begin{equation*}
   \mathsf{W}_1(\mu,\updelta_{x_0})=\sup_{\mathrm{Lip}(g)\leqslant 1}\int g(\mu -\updelta_{x_0} )\leqslant C\cdot\eta_2
\end{equation*}
for some numerical constant $C>0$.
Hence, for $g:\mathbb{S}^{d-1}\to \mathbb{S}^{d-1}$ defined as 
\begin{equation*}
    g(x)=\begin{cases}
        1\quad &x\in B(x,\eta_3)\\
        1-\frac{1-\eta_3}{\eta_3}\quad &x\in B(x,\eta_3)\cap B(x,2\eta_3)\\
        0\quad &x\notin B(x,2\eta_3),
    \end{cases}
\end{equation*}
we obtain
\begin{equation*}
    1-\mu(B(x,\eta_3))\leqslant C\cdot\frac{\eta_2}{\eta_3}.\qedhere
\end{equation*}

In the proof above,
\begin{itemize}
    \item $\Phi_1$ is induced by parameters with $O(N(\eta))$ switches, and therefore depends on the decay of $(\mu(\{x_n\}))_{n\geqslant1}$. If there are finitely many atoms, then there is no dependence on $\eta$.
    \item $\Phi_2$ is induced by parameters where the number of switches depends on the packing numbers of the supports of $\Phi^1_\#\mu_m$---see \Cref{rem: nb.disc.clustering}.
    \item $\Phi_3$ is induced by parameters with  $O(M(\varepsilon))$ switches, where $M(\varepsilon)$ depends on the approximation of $\mathsf{T}^i$ by a simple function. It is worth noting that whenever a simple function with $M$ components is considered as a transport map $\mathsf{T}^i$, the resulting measure $\mathsf{T}^i_\#\mu$ consists of a combination of $M$ atoms. As a consequence, if we have $N$ targets each having $M$ atoms, after disentangling and clustering them, the matching with $\Phi_3$ can be done with $O(M \cdot N)$ switches.
\end{itemize}

\label{lem: squashing.lemma}
Let $\mu_0^i\in \mathscr{P}(\mathbb{S}^{d-1})$, $i\in[N]$, be such that 
\begin{equation*}
\bigcup_{i\in[N]}\mathrm{supp}\left(\mu^i_0\right)\subset\mathbb{S}^{d-1}.
\end{equation*}
For any $i\in[N]$ consider the marginal $\nu^i\in \mathscr{P}(\mathbb{S}^1)$ defined as 
\begin{equation*}
\nu^i(x_1,x_2)=\int_{[0,\pi]^{d-2}}\mu_0^i(x_1,x_2,\, \mathrm{d}\phi_3,\ldots,\, \mathrm{d}\phi_d),
\end{equation*}
where $\phi_k$, $k\geqslant 3$, correspond to angular hyper-spherical coordinates. Then for every $\varepsilon>0$ and $T>0$, there exists $\theta=(\bm{\mathit{V}},\bm{\mathit{B}},\bm{\mathit{W}},\bm{\mathit{U}},b)\in L^\infty((0,T);\Uptheta)$ such that for any $i\in[N]$, the solution $\mu^i\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to \eqref{eq: cauchy.pb} corresponding to the initial data $\mu_0^i$ and parameters $\theta$ satisfies\footnote{We use the standard shorthand $\updelta^{\otimes m}_0(x) = \updelta_0(x_1)\otimes\cdots\otimes\updelta_0(x_m)$ for $x\in\mathbb{R}^m$.}
\begin{equation*}
\mathsf{W}_2\left(\mu^i(T),\nu^i\otimes \updelta_0^{\otimes (d-2)}\right)\leqslant\varepsilon.
\end{equation*}
Moreover, we can take $\bm{\mathit{B}}\equiv\bm{\mathit{V}}\equiv b\equiv0$, and $\bm{\mathit{W}}$ and $\bm{\mathit{U}}$ piecewise constant with at most $2(d-2)$ switches.

The proof is done by induction---it is thus enough to prove that we can ``collapse'' one dimension/coordinate. We begin by the last coordinate.
Consider
\begin{equation*}
\mathscr{P}(\mathbb{S}^{d-2})\ni\nu^i_{k}(x_1,x_2,\ldots,x_{k}):=\int_0^\pi \mu_0^i(x_1,x_2,\ldots,x_{k},\, \mathrm{d}\phi_{k+1},\ldots\, \mathrm{d}\phi_d).
\end{equation*}
With this notation, $\nu^i = \nu^i_{2}$.
Let $T_d>0$ and $\varepsilon_d>0$ to be chosen later on.
Consider
\begin{align*}
\bm{\mathit{U}}_+(t)&={\bf1} e_d^\top,\\
\bm{\mathit{W}}_+(t){\bf1}&=-e_d
\end{align*}
for $t\in[0,T_d]$.
Then on $[0,T_d]$, the characteristics of \eqref{eq: cauchy.pb} become
\begin{equation}\label{eq: squashing.upper.hemisphere}
\begin{cases}
\dot{x}(t)=-\langle e_d,x(t)\rangle_+\bm{\mathsf{P}}^\perp_{x(t)}e_d &\text{ in } [0,T_d] \\
x(0) = x_0.
\end{cases}
\end{equation}
One sees that for any $x_0\in\mathbb{S}^{d-1}\setminus\{e_d\}$ with $\langle x_0, e_d\rangle >0$, we have
$\langle x(t),e_d\rangle \to 0$ as $t\to+\infty$. 
Denoting the flow of \eqref{eq: squashing.upper.hemisphere} as $\Phi^{\frac{t}{2}}_+:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$, and similarly, denoting by $\Phi^{\frac{t}{2}}_-:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ the flow map associated to
\begin{align*}
\bm{\mathit{U}}_-(t)&=-{\bf1} e_d^\top,\\
\bm{\mathit{W}}_-(t){\bf1}&=e_d,
\end{align*}
we have that
\begin{equation*}
\Phi^{\frac{t}{2}}_+\circ \Phi^{\frac{t}{2}}_-=\Phi^{\frac{t}{2}}_-\circ \Phi^{\frac{t}{2}}_+=:\Psi_d^t.
\end{equation*}
(The subscript $d$ indicates the coordinate which we collapsing to the equator.)
Since for any $i\in[N]$, $\mu^i_0$ has no atom at $e_d$ nor at $-e_d$, we can choose $T_d$ such that $\mu^i(T_d)=(\Psi^{T_d}_d)_{\#}\mu_0^i$ satisfies
\begin{equation*}
\mathsf{W}_2\left(\mu^i(T_d),\nu^i_{d-1}\otimes \updelta_{0}\right)\leqslant\varepsilon_d
\end{equation*}
for $i\in[N]$.

Now assume heredity: 
\begin{equation} \label{eq: heredity}
\mathsf{W}_2\left(\left(\Psi_4^{T_4}\circ\cdots\circ \Psi_d^{T_d}\right)_{\#}\mu_0^i,\nu^i_{3}\otimes\updelta^{\otimes(d-3)}_0\right)\leqslant\varepsilon_{4}
\end{equation}
for an arbitrary $\varepsilon_4>0$, $i\in[N]$, and for some flow maps $\Psi_k^{T_k}:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics of \eqref{eq: cauchy.pb}.
For $\varepsilon_3>0$ to be chosen later on, we apply the same reasoning as done above to find a flow map $\Psi_3^{T_3}:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics of \eqref{eq: cauchy.pb} such that
\begin{equation} \label{eq: epsilon.3}
\mathsf{W}_2\left(\left(\Psi_3^{T_3}\right)_\# \nu_{3}^i, \nu^i\otimes\updelta_0^{\otimes(d-3)}\right)\leqslant\varepsilon_3.
\end{equation}
Then using standard continuity estimates for the continuity equation, along with \eqref{eq: epsilon.3}, \eqref{eq: heredity} and the triangle inequality, we deduce
\begin{align*}
&\mathsf{W}_2\left(\left(\Psi_3^{T_3}\circ\Psi_4^{T_4}\circ\cdots\circ \Psi_d^{T_d}\right)_{\#}\mu_0^i,\nu^i\otimes\updelta^{\otimes(d-3)}_0\right)\\
&\hspace{2cm}\leqslant\mathsf{W}_2\left(\left(\Psi_3^{T_3}\circ \Psi_4^{T_4}\circ\cdots\circ\Psi_d^{T_d}\right)_{\#}\mu_0^i, \left(\Psi_3^{T_3}\right)_\# \nu_{3}^i\right) \\
&\hspace{4cm} + \mathsf{W}_2\left(\left(\Psi_3^{T_3}\right)_\# \nu_{3}^i, \nu^i\otimes\updelta_0^{\otimes(d-2)} \right)\\
&\hspace{2cm}\leqslant C({\varepsilon_3}) \varepsilon_4 + \varepsilon_3
\end{align*}
    for some $C({\varepsilon_3})>0$. We may choose $\varepsilon_4$ and $\varepsilon_3$ small enough to conclude.

\label{lem: feedback}
   Let $T>0$. Consider $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$, $i\in[N]$ satisfying
   \begin{equation*}
       \partial\mathrm{supp}(\nu_0^i)\cap \partial\mathrm{supp}(\nu_0^j)=\varnothing\hspace{1cm} \text{ for } i\neq j,
   \end{equation*}
   where, as before, $\nu_0^i\in\mathscr{P}(\mathbb{S}^1)$ denotes the marginal
   $$\nu_0^i(x_1,x_2) = \int_{[0,\pi]^{d-2}} \mu_0^i(x_1,x_2,\, \mathrm{d}\phi_3,\ldots,\, \mathrm{d}\phi_d).$$
   Then there exists $\theta\in L^\infty((0,T);\Uptheta)$ such that
       \begin{equation*}
       \mathrm{supp}\left(\mu^i(T)\right)\cap \mathrm{supp}\left(\mu^j(T)\right)=\varnothing\hspace{1cm} \text{ for } i\neq j.
   \end{equation*}

     We proceed in several steps. Throughout, $\bm{\mathit{V}}\equiv I_d$ and $b\equiv0$.


\subsubsection*{Step 1. Squashing to the equator; transporting to the first orthant}

By virtue of \Cref{lem: squashing.lemma}, for any $\varepsilon>0$ we can find a flow map $\Phi_{\varepsilon}:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics of \eqref{eq: cauchy.pb} such that 
\begin{equation} \label{eq: almost.first.quadrant}
    \mathsf{W}_2\left(\Phi_{\varepsilon\#}\mu_0^i, \eta_0^i\otimes\updelta_0^{\otimes(d-2)}\right)\leqslant\varepsilon,
\end{equation}
where $\eta^i_0=\Psi_\#\nu_0^i\in\mathscr{P}(\mathbb{S}^1\cap(\mathbb{R}_{\geqslant0})^2)$, with $\Psi$ being the flow map given by \Cref{lem: first.quadrant}. Since $\varepsilon>0$ can be chosen arbitrarily small, by virtue of \eqref{eq: almost.first.quadrant} we can,  without loss of generality, assume that $\mu_0^i$ are defined on $\mathbb{Q}_1^1:=\mathbb{S}^1\cap(\mathbb{R}_{\geqslant0})^2$. 

\subsubsection*{Step 2. Creating an atom at the argmax}

We order (and relabel) the measures $\mu^i_0$ by decreasing order of the respective magnitude of 
$$x^{i+}:=\mathop{\mathrm{arg\,max}}\limits_{x\in\mathrm{supp}(\mu^i_0)}\langle x, e_2\rangle.$$
Let $\eta>0$ be chosen later on.
We apply \Cref{lem: two.balls} with $\mathscr{B}_0=B(x^{+1},\rho)$, where $\rho<d_g(x^{+1},x^{+2})$, and $\mathscr{B}_1=B(x^{+1},\eta)$, and by choosing $\omega=x^{+1}$ in the proof, it follows that there exists some time $T_1(\eta)>0$ such that
\begin{equation} \label{eq: atom.in.argmax}
    \mathsf{W}_2\left(\mu^1(T_1(\eta)),\alpha\right)\leqslant\delta,
\end{equation}
where 
\begin{equation*}
    \alpha(A)=\mu_0^1(\mathscr{B}_0)\updelta_{x^{1+}}(A)+\mu_0^1(A\setminus \mathscr{B}_0)
\end{equation*}
for any Borel $A\subset\mathbb{S}^1$.
Furthermore, due to the choice of $\rho$, we have 
\begin{equation*}
    \mu^{i}(T_1(\eta))=\mu_0^i
\end{equation*}
for $2\leqslant i\leqslant N$.

\subsubsection*{Step 3. A feedback to counter attention}

Let $T_2(\eta)>T_1(\eta)$ be chosen later on.
For $t\in[T_1(\eta), T_2(\eta)]$ we choose 
$$\bm{\mathit{U}}(t)\equiv {\bf1}^\top a$$ 
where $a\in\mathbb{S}^1$ is such that
\begin{align*}
    \langle a, x^{1+}\rangle&>0,\\
    \langle a,x\rangle&<0\hspace{1cm}\text{for }x\in \bigcup_{j=2}^N \mathrm{supp}(\mu_0^j).
\end{align*}
(As such, the perceptron component of the vector field vanishes for $2\leqslant i\leqslant N$.)
We then define $\bm{\mathit{W}}(t)$ in feedback form:
\begin{equation}\label{eq: feedback.W}
    \left(\left\langle a,x^{1+}\right\rangle\right)_+\bm{\mathit{W}}(t){\bf1}+\mathscr{A}_{\bm{\mathit{B}}}\left[\mu^1(t)\right](x^{1+})=x^{1+}.
\end{equation}
(In this way, after applying $\bm{\mathsf{P}}^\perp_x$, the atom located at $x^{1+}$ remains invariant.)
Equivalently,
\begin{equation*}
    \bm{\mathit{W}}(t)1=\frac{1}{\left(\left\langle a,x^{1+}\right\rangle\right)_+}\left(x^{1+}-\mathscr{A}_{\bm{\mathit{B}}}\left[\mu^1(t)\right](x^{1+})\right).
\end{equation*}
Note that $\bm{\mathit{W}}(t)$ can be chosen to be a diagonal matrix. Since we now operate on $\mathbb{Q}_1^1$, and the vector field $x\mapsto\bm{\mathit{W}}(\bm{\mathit{U}} x)_+$ does not affect $\mu_0^i$ for $2\leqslant i\leqslant N$, the solution to the Cauchy problem \eqref{eq: cauchy.pb} emanating from $\mu_0^i$ converges weakly to 
a point mass $\updelta_{z^i}$ as $t\to+\infty$, for some $z^i$ lying in $\mathrm{conv}_g \,\mathrm{supp}(\mu^i_0)$ (see \Cref{prop: targets.atoms}, or the arguments of \cite[Theorem 4.1]{geshkovski2023mathematical}).
On the other hand, thanks to \eqref{eq: atom.in.argmax} and the definition of the feedback $\bm{\mathit{W}}(t)$, we also have a way of identifying the position $z^1$ of the limit $\updelta_{z^1}$ for the solution emanating from  $\mu_0^1$. 
Indeed, let us choose $\bm{\mathit{B}}\in\mathscr{M}_{2\times 2}(\mathbb{R})$ such that
\begin{align*}
    \bm{\mathit{B}} x^{1+}&=\beta x^{1+}\\ 
    \bm{\mathit{B}} x&=0 \quad\text{ for $x\in\mathbb{S}^1$ such that $\langle x,x^{1+}\rangle=0$},
\end{align*}
where the eigenvalue $\beta>0$ is to be chosen later on. Observe that if, for every $\varepsilon>0$, there exists a $\beta>0$ such that the solution to \eqref{eq: cauchy.pb} for $\mu^1(t)$ in the interval $(0,+\infty)$ satisfies
\begin{equation}\label{eq: attention.set}
    \mathscr{A}_{\bm{\mathit{B}}}[\mu^1(t)](x)\in sB(x^{1+},C\varepsilon)
\end{equation}
for $s\geqslant c>0$, then, for every $\delta>0$ there exists $T_*$ for which
\begin{equation*}
    \mathrm{supp}\left(\mu^1(T_*)\right)\subset B(x^{1+},C\varepsilon+\delta)
\end{equation*}
We prove that the solution $\mu^1\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^1))$, whenever $\mu_0^1$ has an atom at $x^{1+}$, satisfies \eqref{eq: attention.set}. 
\begin{enumerate}
    \item Consider
    $$\mathscr{C}:=\mathrm{conv }(\mathbb{Q}_1^1).$$ 
For every $\mu\in\mathscr{P}(\mathbb{Q}_1^1)$ and $x\in\mathrm{supp}(\mu)$ one has
$\mathscr{A}_{\bm{\mathit{B}}}[\mu](x)\in\mathscr{C}$ since $\mathscr{A}_{\bm{\mathit{B}}}[\mu](x)$ is a weighted average of the elements of the support of $\mu$. This implies that 
\begin{equation}\label{eq: low.bound.attention}
    \|\mathscr{A}_{\bm{\mathit{B}}}[\mu](x)\|\geqslant c
\end{equation}
for some $c>0$ and for every $x\in\mathrm{supp}(\mu)$. 

\item  Thanks to \eqref{eq: low.bound.attention}, it only remains to assess the direction in which $\mathscr{A}_{\bm{\mathit{B}}}[\mu](x)$ is pointing. If $\varepsilon>0$ is fixed, and for every $\mu$ that has an atom at $x^{1+}$, we notice that we can decompose the integral in three parts
\begin{align*}
    e^{-\beta}\int e^{\langle \bm{\mathit{B}} x,x'\rangle }x'\mu(\, \mathrm{d} x')&=\mu(\{x^{1+}\})x^{1+}\\
    &+\int_{B(x^{1+},\varepsilon)\backslash \{x^{1+}\}}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x')\\
    &+\int_{\mathbb{S}^{d-1}\setminus B(x^{1+},\varepsilon)}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x'),
\end{align*}
The above identity is a sum of three vectors with
\begin{align*}
    \|w\|&:=\left\|\int_{B(x^{1+},\varepsilon)\backslash \{x^{1+}\}}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x')\right\|\\
    &\leqslant \mu\left(B(x^{1+},\varepsilon)\backslash \{x^{1+}\}\right),
\end{align*}
as well as
\begin{equation*}
    \|v\|:=\left\|\int_{\mathbb{S}^{d-1}\setminus B(x^{+1},\varepsilon)}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x')\right\|\leqslant e^{-O(\beta\varepsilon^2)},
\end{equation*}
where the last bound stems from a Taylor expansion of $\langle x^{1+},x'\rangle$, and the implicit constant is universal. Applying this to $\mu^1(t,\cdot)$ for any $t\in[T_1(\eta), T_2(\eta)]$, and choosing $\beta=\varepsilon^{-3}$ so that $|v|$ goes to zero as $\varepsilon$ goes to zero, we deduce
\begin{equation*}
    \mu^1(t, \{x^{1+}\})x^{1+}+w+v\in sB(x^{1+},C\varepsilon)
\end{equation*}
for some $C>0$ independent of $\varepsilon, t$, and for some $s\in[c, 1]$. Since $x^{1+}$ is invariant by \eqref{eq: feedback.W}, $\mu(t,x^{1+})=\mu(0,x^{1+})$ and we deduce \eqref{eq: attention.set}.
\end{enumerate}


\subsubsection*{Step 4. Clustering and separation} 

Because of the choice of $\bm{\mathit{U}}$ and $\bm{\mathit{V}}$, for $i\in[N]$ we have
\begin{equation*}
    \mathrm{supp}\left(\mu^i(t)\right)\subset \mathrm{supp}\left(\mu^i_0\right)
\end{equation*}
for any $t\in[T_1(\eta), T_2(\eta)]$. Let $\varepsilon<\rho$ be small enough so that for any $x\in\mathrm{supp}(\mu^1(t))$, we have
$\mathscr{A}_{\bm{\mathit{B}}}(x)\in sB(x^{1+},d_g(x^{1+},x^{2+})) $ where $s\in[c,1]$. It follows that we can choose $T_2(\eta)>0$ large enough so that $\mathrm{supp} (\mu^1(T_2(\eta)))\subset B(x^{1+},d_g(x^{1+},x^{2+}))$, and hence, 
\begin{equation*}
    \mathrm{supp}\left(\mu^1(T_2(\eta))\right) \cap \mathrm{supp}\left(\mu^i(T_2(\eta))\right)=\varnothing
\end{equation*}
for $2\leqslant i\leqslant N$.

\subsubsection*{Step 5. Rotation and induction}

For convenience, we relabel the measures obtained from the previous step by resetting time: $\mu_0^i=\mu^i(T_2(\eta))$. 
In this last step, we set $\bm{\mathit{V}}\equiv0$, to send the first measure counter-clockwise to $\mathbb{Q}^1_1$ so that it has disjoint support with the other measures, and so that $\langle x^{1+}, e_2\rangle$ is smaller than the infimum of $x\mapsto\langle x, e_2\rangle$ over the supports of all the other measures. This argument can then be repeated for every $i\in[N]$. To do so, let $T_1>0$ to be chosen later, and
$$\bm{\mathit{U}}(t)\equiv {\bf1}a^\top$$ 
for $t\in[0,T_1]$
with $a\in\mathbb{S}^1$ satisfying
\begin{equation*}
    \langle a,z\rangle=0
\end{equation*}
for all $z\in\mathbb{S}^1$ with $\langle z-y,e_2\rangle>0$ for all $y\in \bigcup_{j=2}^N \mathrm{supp}(\mu_0^j)$ and $\langle z-y, e_2\rangle<0$ for all $y\in \mathrm{supp}(\mu^1_0)$.
Define
\begin{equation*}
    \mathscr{S}_a:=\left\{ x\in \mathbb{S}^1: \langle a,x\rangle >0 \right\},
\end{equation*}
take $\omega\in \mathscr{S}_a\cap \mathrm{int}(\mathbb{Q}_4^1)$, and choose
\begin{equation*}
    \bm{\mathit{W}}(t){\bf1}\equiv\omega
\end{equation*}
for $t\in[0,T_1]$. (Here $\mathbb{Q}_4^1:=\mathbb{S}^1\cap\{x\in\mathbb{R}^2\colon x_1>0, x_2<0\}$.)
We can choose $T_1>0$ large enough so that
\begin{equation*}
\mathrm{supp}\left(\mu^1(T_1)\right)\subset\mathrm{int}\left(\mathbb{Q}_4^1\right),
\end{equation*}
while the rest of the measures remain invariant: $\mu^i(T_1) = \mu^i_0$ for $2\leqslant i\leqslant N$. Now let $T_2>T_1$ to be chosen later, and $\bm{\mathit{U}}(t)\equiv{\bf1}a_2^\top$ for $t\in[T_1,T_2]$, where $a_2$ is such that
\begin{equation*}
\mathscr{S}_{a_2}\cap\mathrm{int}\left(\mathbb{Q}_1^1\right)\neq\varnothing, \hspace{1cm} \omega\in\mathrm{int}(\mathscr{S}_{a_2}),\hspace{1cm} \mathscr{S}_{a_2}\cap \bigcup_{j=2}^N\mathrm{supp}\left(\mu_0^j\right) =\varnothing.
\end{equation*}
Then fix $\omega_2\in\mathrm{int}(\mathbb{Q}_1^1)\cap \mathscr{S}_{a_2}$ and proceed as before to find a $T_2>0$ large enough so that
\begin{equation*}
    \mathrm{supp}\left(\mu^1(T_2)\right)\subset \mathrm{int}\left(\mathbb{Q}_1^1\right)\cap\mathscr{S}_{a_2}
\end{equation*}
then, by this argument, the intersection between the support of the first measure and all the others is empty. Furthermore, notice that from Step 3 of this proof, we have
\begin{equation*}
    \mathrm{supp}\left(\mu^j(T)\right)\subset\mathrm{supp}\left(\mu_0^j\right) \hspace{1cm} \text{ for } j\in[N].
\end{equation*}
Consequently, if two measures $\mu^i_0$ and $\mu^j_0$ had disjoint support, the supports of $\mu^j(T)$ and $\mu^i(T)$ would remain disjoint for all $T>0$. We can inductively repeat the whole argument simply by relabelling the measures as
\begin{equation*}
    \mu_0^i:=\mu^{i+1}(T_2)\hspace{1cm }\text{ for } i\in[N-1],
\end{equation*}
and
\begin{equation*}
    \mu_0^N:=\mu^{1}(T_2),
\end{equation*}
to conclude.

\begin{align*}
    \bm{\mathit{B}} x^{1+}&=\beta x^{1+}\\ 
    \bm{\mathit{B}} x&=0 \quad\text{ for $x\in\mathbb{S}^1$ such that $\langle x,x^{1+}\rangle=0$},
\end{align*}

\begin{align*}
    e^{-\beta}\int e^{\langle \bm{\mathit{B}} x,x'\rangle }x'\mu(\, \mathrm{d} x')&=\mu(\{x^{1+}\})x^{1+}\\
    &+\int_{B(x^{1+},\varepsilon)\backslash \{x^{1+}\}}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x')\\
    &+\int_{\mathbb{S}^{d-1}\setminus B(x^{1+},\varepsilon)}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x'),
\end{align*}

\begin{equation*}
    \|v\|:=\left\|\int_{\mathbb{S}^{d-1}\setminus B(x^{+1},\varepsilon)}  e^{\beta \langle x,x'\rangle\langle x^{1+},x'\rangle-\beta }x'\mu(\, \mathrm{d} x')\right\|\leqslant e^{-O(\beta\varepsilon^2)},
\end{equation*}
